window.ATLAS_ITEMS=window.ATLAS_ITEMS||{};window.ATLAS_ITEMS[225]={"id":"225","numero":225,"titre":"Artériopathies de l'aorte, des artères viscérales et des MI","objectifs":[{"id":"225-1","rang":"A","rubrique":"Définition","titre":"Connaître la définition et la fréquence de l’artériopathie oblitérante des membres inférieurs (AOMI)","contenu":"<div class=\"notion-course\"><p>L'<span>AOMI</span> est définie par la présence de <span>lésions d'athérosclérose de l'aorte et des artères des membres inférieurs</span>, pouvant entraîner des <span><span class=\"nc-red\">plaques</span></span>, des <span><span class=\"nc-red\">sténoses</span></span> ou des <span><span class=\"nc-red\">obstructions</span></span> athéromateuses d'une ou plusieurs artères destinées aux membres inférieurs. Elle représente l'<span>expression locale d'une maladie systémique</span> : le <span>pronostic</span> est en grande partie conditionné par les complications cardiaques et cérébrovasculaires.</p>\n      <p>L'origine athéromateuse domine très largement : l'AOMI correspond à <span>&gt; 95 %</span> des atteintes artérielles oblitérantes des membres inférieurs.</p>\n      <p><strong>Fréquence</strong> — la <span>prévalence</span> augmente avec l'âge et atteint <span>&gt; 20 %</span> au-delà de <span>70 ans</span>. Elle doit être <strong>recherchée systématiquement</strong> à partir de <span>60 ans</span>.</p>\n      <table>\n        <thead>\n          <tr><th><span>Pronostic</span></th><th>Donnée chiffrée</th></tr>\n        </thead>\n        <tbody>\n          <tr><td><span>Claudication</span> intermittente</td><td>Espérance de vie réduite en moyenne de <span><span class=\"nc-red nc-bold\">-10 ans</span></span></td></tr>\n          <tr><td><span>Stade</span> d'ischémie d'effort (<span>claudication</span>)</td><td>Le risque d’amputation est nettement plus élevé en ischémie chronique menaçant le membre qu’en simple claudication. Il dépend de la perfusion, des plaies, de l’infection et de la possibilité de revascularisation.</td></tr>\n          <tr><td><span>Stade</span> d'<span class=\"nc-brown_bg\">ischémie permanente</span> chronique (symptômes de repos)</td><td><span>Mortalité</span> <span><span class=\"nc-pink_bg\">25 % à 1 an</span></span> et <span><span class=\"nc-pink_bg\">70 % à 5 ans</span></span></td></tr>\n        </tbody>\n      </table>\n      <p class=\"obj-renvois\"><em>📎 Items liés : 221 — <span>Athérome</span></em></p></div><details><summary>Sources et compléments</summary><p>Relecture du 15 octobre 2026. Couleurs reprises des passages correspondants de ton cours Notion.</p><ul><li><a href=\"https://app.notion.com/p/2ad37f85d941812997bdd5a47ff348db?pvs=204\" target=\"_blank\" rel=\"noopener noreferrer\">Ton cours Notion · Artériopathie oblitérante des membres inférieurs</a></li><li><a href=\"https://www.sfcardio.fr/publication/chapitre-07-item-225-arteriopathie-de-laorte-des-arteres-viscerales-et-des-membres-inferieurs-anevrismes/\" target=\"_blank\" rel=\"noopener noreferrer\">CNEC · Item 225</a></li><li><a href=\"https://esvs.org/guidelines/\" target=\"_blank\" rel=\"noopener noreferrer\">ESVS · Recommandations vasculaires</a></li></ul><p>Les compléments ATLAS sont des synthèses pédagogiques ; les repères historiques et les recommandations plus récentes sont distingués lorsque nécessaire.</p></details>","frequence":0},{"id":"225-2","rang":"B","rubrique":"Physiopathologie","titre":"Connaître l’étiologie et les facteurs de risque de l’AOMI","contenu":"<div class=\"notion-course\"><p>L'<span>origine athéromateuse</span> de l'AOMI est de très loin la plus fréquente (<span>&gt; 95 %</span>). L'AOMI est l'expression locale d'une maladie systémique : son <span>pronostic</span> est conditionné par les atteintes <span>cardiaques</span> (<span>angor</span>, <span>infarctus du myocarde</span>) et <span>cérébrovasculaires</span> associées.</p>\n      <p><strong><span>Facteurs de risque</span></strong> — ce sont les <span>facteurs de risque cardiovasculaire</span> : âge, <span><span class=\"nc-red_bg\">tabac</span></span>, <span><span class=\"nc-red_bg\">diabète</span></span>, <span>HTA</span>, <span>hypercholestérolémie</span>. Les <strong>FR dominants</strong> de l'AOMI sont le <span><span class=\"nc-red_bg\">tabac</span></span> et le <span><span class=\"nc-red_bg\">diabète</span></span>.</p>\n      <p><strong>Artériopathies non athéromateuses</strong> — elles représentent moins de <span>5 %</span> des atteintes oblitérantes des membres inférieurs :</p>\n      <ul>\n        <li><strong>Artériopathies inflammatoires :</strong> maladie de <span><span class=\"nc-orange_bg\">Buerger</span></span>, <span><span class=\"nc-orange_bg\">Takayasu</span></span>, <span><span class=\"nc-orange_bg\">Horton</span></span>, certaines collagénoses (<span class=\"nc-orange_bg\">périartérite noueuse</span>, <span><span class=\"nc-orange_bg\">lupus</span></span>).</li>\n        <li><strong><span class=\"nc-orange_bg\">Dysplasie fibromusculaire</span> :</strong> au niveau iliaque ou poplité.</li>\n        <li><strong><span class=\"nc-orange_bg\">Coarctation de l'aorte</span> :</strong> cause d'hypodébit en aval.</li>\n        <li><strong>Atteintes acquises :</strong> post-radiques, post-traumatiques, toxiques (dérivés de l'ergot de seigle), <span class=\"nc-blue_bg\">gelures</span>, compressions extrinsèques.</li>\n        <li><strong>Atteintes spécifiques de l'artère <span class=\"nc-pink nc-bold\">poplitée</span> :</strong> artère <span class=\"nc-pink nc-bold\">poplitée</span> piégée, kyste poplité sous-adventiciel.</li>\n      </ul>\n      <p class=\"obj-renvois\"><em>📎 Items liés : 221 — <span>Athérome</span> · 223 — <span>Dyslipidémie</span> · 224 — <span>HTA</span> · 247 — <span><span class=\"nc-red_bg\">Diabète</span></span> · 75 — Addiction <span>Tabac</span></em></p></div><details><summary>Sources et compléments</summary><p>Relecture du 15 octobre 2026. Couleurs reprises des passages correspondants de ton cours Notion.</p><ul><li><a href=\"https://app.notion.com/p/2ad37f85d941812997bdd5a47ff348db?pvs=204\" target=\"_blank\" rel=\"noopener noreferrer\">Ton cours Notion · Artériopathie oblitérante des membres inférieurs</a></li><li><a href=\"https://www.sfcardio.fr/publication/chapitre-07-item-225-arteriopathie-de-laorte-des-arteres-viscerales-et-des-membres-inferieurs-anevrismes/\" target=\"_blank\" rel=\"noopener noreferrer\">CNEC · Item 225</a></li><li><a href=\"https://esvs.org/guidelines/\" target=\"_blank\" rel=\"noopener noreferrer\">ESVS · Recommandations vasculaires</a></li></ul><p>Les compléments ATLAS sont des synthèses pédagogiques ; les repères historiques et les recommandations plus récentes sont distingués lorsque nécessaire.</p></details>","frequence":0},{"id":"225-3","rang":"A","rubrique":"Diagnostic positif","titre":"Connaître les manifestations cliniques et la classification de l’AOMI et savoir évoquer les diagnostics différentiels","contenu":"<div class=\"notion-course\"><p>Les chirurgiens vasculaires utilisent une <span>classification clinico-hémodynamique</span> en 3 stades. La <span>classification</span> de <span>Leriche &amp; Fontaine</span> est <strong>abandonnée</strong> (faussement rassurante, basée uniquement sur les symptômes et suggérant une succession chronologique erronée) — mais elle reste à connaître.</p>\n      <table>\n        <thead>\n          <tr><th><span>Stade</span></th><th>Clinique</th><th>Hémodynamique</th></tr>\n        </thead>\n        <tbody>\n          <tr><td><strong>Asymptomatique</strong></td><td>Aucun symptôme</td><td><span>IPS ≤ 0,9</span> ; PA cheville <span>&gt; 50 mmHg</span></td></tr>\n          <tr><td><strong>Ischémie d'effort</strong></td><td><span>Claudication intermittente</span></td><td><span>IPS ≤ 0,9</span> ; PA cheville <span><span class=\"nc-pink nc-bold\">&gt; 50 mmHg</span></span></td></tr>\n          <tr><td><strong><span class=\"nc-brown_bg\">Ischémie permanente</span></strong></td><td><span>Douleurs de décubitus</span> au repos ± <span>troubles trophiques</span></td><td><span>IPS ≤ 0,9</span> ; PA cheville <span>≤ 50 mmHg</span> ; <span class=\"nc-red_bg\">pression d'orteil </span><span><span class=\"nc-red_bg\">&lt; 30 mmHg</span></span> ; <span>TcPO2 <span class=\"nc-pink nc-bold\">&lt; 30 mmHg</span></span></td></tr>\n        </tbody>\n      </table>\n      <p><strong>Classifications historiques</strong> (à connaître). <span>Leriche &amp; Fontaine</span> — 4 stades : I asymptomatique · II <span>claudication</span> (ischémie d'effort) · III <span>douleur de repos</span> (ischémie critique) · IV <span>ulcération ou gangrène</span>. <span>Rutherford</span> — plus détaillée, grades 0 à III avec catégories 0 à 6. La dichotomie <span>ischémie aiguë</span> / chronique se fait sur un <strong>cut-off à <span><span class=\"nc-pink nc-bold\">15 jours</span></span></strong>.</p>\n\n      <h4 style=\"margin:16px 0 6px;font-size:14px;\"><span>Stade</span> 1 — forme asymptomatique</h4>\n      <p>À évoquer devant un <span><span class=\"nc-blue_bg\">souffle vasculaire</span></span> ou une <span><span class=\"nc-blue_bg\">abolition de pouls périphériques</span></span> chez un sujet à <span>FRCV</span>, ou une <span>dysfonction érectile</span> chez un patient à FRCV. Confirmation : <span>IPS ≤ 0,90</span>.</p>\n      <div class=\"callout callout-warn\">\n        <strong>Piège — la forme masquée.</strong> Une atteinte sévère peut rester asymptomatique : développement d'une <span>circulation collatérale</span>, sujet âgé peu mobile, <span>neuropathie</span> (<span><span class=\"nc-red_bg\">diabète</span></span>, <span>IRC</span>) altérant la sensibilité. Le patient peut alors présenter d'emblée une <span>forme grave d'<span class=\"nc-brown_bg\">ischémie permanente</span></span> en paraissant asymptomatique peu de temps avant.\n      </div>\n\n      <h4 style=\"margin:16px 0 6px;font-size:14px;\"><span>Stade</span> 2 — ischémie d'effort (<span>claudication</span> intermittente)</h4>\n      <ul>\n        <li><strong>Type :</strong> <span><span class=\"nc-yellow_bg\">crampe</span></span>.</li>\n        <li><strong>Topographie :</strong> <span><span class=\"nc-yellow_bg\">mollet</span></span> typiquement.</li>\n        <li><strong>Distance de gêne :</strong> distance à laquelle la douleur apparaît ; <strong>distance de marche :</strong> distance à laquelle la douleur oblige à l'arrêt — <span><span class=\"nc-red_bg\">AOMI sévère</span> si <span class=\"nc-red nc-bold\">distance de marche &lt; 100 m sur terrain plat</span></span>.</li>\n        <li><strong>Disparition :</strong> habituellement en <span><span class=\"nc-green_bg nc-bold\">&lt; 5 minutes</span></span> à l'arrêt.</li>\n      </ul>\n      <p>Formes atypiques fréquentes : distances variables, topographies autres (pied, <span class=\"nc-yellow_bg\">cuisse</span>, <span>claudication fessière</span> par atteinte <span class=\"nc-pink nc-bold\">aorto-iliaque</span>), <span class=\"nc-brown_bg\">paresthésie</span> d'effort, ralentissement du pas sans arrêt obligé.</p>\n\n      <h4 style=\"margin:16px 0 6px;font-size:14px;\">Stades 3-4 — <span class=\"nc-brown_bg\">ischémie permanente</span> / critique</h4>\n      <ul>\n        <li><strong>Douleur de repos (<span>stade</span> 3) :</strong> à type de <span><span class=\"nc-yellow_bg\">brûlure</span></span> ; topographie <span><span class=\"nc-yellow_bg\">orteil</span> / <span class=\"nc-yellow_bg\">avant-pied</span></span> ; survient après quelques minutes à quelques heures de décubitus ; <span>calmée en <span class=\"nc-green_bg\">position déclive</span></span> (jambes pendantes au bord du lit).</li>\n        <li><strong>Troubles trophiques (<span>stade</span> 4) :</strong> <span class=\"nc-blue_bg\">peau mince</span> et <span class=\"nc-blue_bg\">fragile</span>, <span class=\"nc-red_bg\">dépilation</span> ; <span><span class=\"nc-red_bg\">ulcère artériel</span></span> ; <span><span class=\"nc-red_bg\">gangrène</span></span> (<span class=\"nc-blue nc-bold\">orteils</span>, <span class=\"nc-blue nc-bold\">talon</span>) ; portes d'entrée infectieuses.</li>\n      </ul>\n      <div class=\"callout callout-danger\">\n        <strong><span class=\"nc-brown_bg\">Ischémie permanente</span> — <span>pronostic</span> du membre engagé.</strong> Douleurs durant <span><span class=\"nc-pink nc-bold\">&gt; 15 jours</span></span>, résistant aux <span>antalgiques</span> usuels ; pressions de perfusion effondrées (<span><span class=\"nc-pink nc-bold\">&lt; 50 mmHg</span></span> à la cheville, <span><span class=\"nc-red_bg\">&lt; 30 mmHg</span></span><span class=\"nc-red_bg\"> à l'hallux</span>). Haut risque d'<span>amputation</span> en l'absence de <span>revascularisation</span>.\n      </div>\n\n      <h4 style=\"margin:16px 0 6px;font-size:14px;\">Localiser la sténose ou l'obstruction</h4>\n      <p>Une <strong>sténose</strong> donne un <span><span class=\"nc-blue_bg\">souffle</span></span> ; une <strong>obstruction</strong> donne une <span><span class=\"nc-blue_bg\">abolition de pouls en aval</span></span> sans <span class=\"nc-blue_bg\">souffle</span>. Le siège de la douleur oriente vers l'artère atteinte :</p>\n      <table>\n        <thead>\n          <tr><th>Siège de la douleur</th><th>Artère en cause</th></tr>\n        </thead>\n        <tbody>\n          <tr><td><span class=\"nc-yellow_bg\">Fesse</span></td><td>Artère iliaque <span class=\"nc-pink nc-bold\">commune</span> ou <span class=\"nc-pink nc-bold\">iliaque interne</span> (hypogastrique)</td></tr>\n          <tr><td><span class=\"nc-yellow_bg\">Cuisse</span></td><td>Artère <span class=\"nc-pink nc-bold\">iliaque externe</span> ou <span class=\"nc-pink nc-bold\">fémorale commune</span></td></tr>\n          <tr><td><span class=\"nc-yellow_bg\">Mollet</span></td><td>Artère <span class=\"nc-pink nc-bold\">fémorale superficielle</span> ou <span class=\"nc-pink nc-bold\">poplitée</span></td></tr>\n          <tr><td>Pied</td><td>Artères du pied ou de la jambe</td></tr>\n        </tbody>\n      </table>\n      <figure class=\"obj-figure\">\n        <img src=\"../assets/images/225/arbre-arteriel-membre-inferieur.png\" alt=\"Schéma de l&#x27;arbre artériel du membre inférieur : iliaque commune, fémorale, poplitée, artères tibiales\" loading=\"lazy\">\n        <figcaption>Arbre artériel du membre inférieur — le siège de la <span>claudication</span> renseigne sur le niveau de la <span>lésion</span>. Source : fiche source EDN item 225.</figcaption>\n      </figure>\n      <p><strong><span>Syndrome de Leriche</span></strong> — atteinte <span><span class=\"nc-pink nc-bold\">aorto-iliaque</span></span> (aorte sous-rénale + artères iliaques primitives) associant : <span>claudication fessière bilatérale</span> et/ou fatigabilité à la marche, <span>dysfonction érectile</span> chez l'homme, <span>abolition des 2 pouls fémoraux</span> et atrophie musculaire des membres inférieurs.</p>\n      <figure class=\"obj-figure\">\n        <img src=\"../assets/images/225/arteres-pelviennes.png\" alt=\"Schéma des artères pelviennes : aorte abdominale, iliaques commune et externe, fémorale commune\" loading=\"lazy\">\n        <figcaption>Artères pelviennes et aorto-iliaques — territoire du syndrome de Leriche. Source : fiche source EDN item 225.</figcaption>\n      </figure>\n\n      <h4 style=\"margin:16px 0 6px;font-size:14px;\"><span><span class=\"nc-red_bg\">Ulcère artériel</span></span> <span>vs</span> <span>ulcère veineux</span> (pivot EDN)</h4>\n      <table>\n        <thead>\n          <tr><th></th><th>Ulcère veineux</th><th><span class=\"nc-red_bg\">Ulcère artériel</span></th></tr>\n        </thead>\n        <tbody>\n          <tr><td><span>Terrain</span></td><td>Femme &gt;<span> 50 ans</span> ; ATCD de <span>TVP</span>, varices, <span>surpoids</span></td><td>Homme &gt;<span> 50 ans</span> ; <span>FRCV</span>, ATCD de <span>claudication</span></td></tr>\n          <tr><td>Localisation</td><td><span class=\"nc-yellow_bg\">Péri-malléolaire</span>, bord <span class=\"nc-green nc-bold\">régulier</span></td><td>Zones d'appui / frottement : <span><span class=\"nc-yellow_bg\">pied</span></span> (<span class=\"nc-yellow_bg\">orteil</span>, <span class=\"nc-blue nc-bold\">talon</span>), parfois ulcère « suspendu » à la face antérieure de jambe</td></tr>\n          <tr><td>Douleur</td><td>Peu ou pas <span class=\"nc-red_bg\">douloureux</span></td><td><span><span class=\"nc-red_bg\">Douloureux</span> ++</span> (souvent intense)</td></tr>\n          <tr><td>Profondeur / fond</td><td><span class=\"nc-green_bg\">Superficiel</span>, exsudatif, <span class=\"nc-blue_bg\">fibrineux</span></td><td><span><span class=\"nc-red_bg\">Creusant</span></span> (risque d'exposition tendineuse/osseuse), <span class=\"nc-green_bg\">fond atone</span> et pâle</td></tr>\n          <tr><td><span>IPS</span></td><td>Normal (0,9 - 1,3)</td><td>Diminué <span>&lt; 0,9</span> ; mixte si 0,7 - 0,9</td></tr>\n          <tr><td>Peau péri-ulcéreuse</td><td>Dermite ocre, atrophie blanche, <span>eczéma</span> variqueux, examen artériel normal</td><td>Peau luisante et <span class=\"nc-green\">dépilée</span>, baisse de température cutanée, <span>abolition des pouls</span></td></tr>\n        </tbody>\n      </table>\n\n      <h4 style=\"margin:16px 0 6px;font-size:14px;\">Diagnostics différentiels de la <span>claudication</span></h4>\n      <table>\n        <thead>\n          <tr><th>Origine</th><th>Distance d'apparition</th><th>Douleur / récupération</th><th>Contexte</th></tr>\n        </thead>\n        <tbody>\n          <tr><td><strong>Artérielle</strong></td><td>La claudication artérielle est reproductible pour un niveau d’effort donné, avec distance variable selon pente, vitesse et conditions ; elle cède généralement rapidement à l’arrêt.</td><td><span><span class=\"nc-yellow_bg\">Crampe</span></span> musculaire obligeant à l'arrêt ; récupération <strong>rapide</strong></td><td>Contexte <span>athéromateux</span></td></tr>\n          <tr><td><strong>Veineuse</strong></td><td>Variable</td><td>Gonflement douloureux progressif n'obligeant pas à l'arrêt ; récupération lente</td><td>Syndrome post-<span>thrombotique</span></td></tr>\n          <tr><td><strong>Articulaire</strong></td><td>Dès les premiers pas</td><td>Topographie articulaire, d'emblée maximale ; récupération lente</td><td>Arthrose, rhumatisme <span>inflammatoire</span></td></tr>\n          <tr><td><strong>Neurologique</strong></td><td>Variable</td><td>Soulagée par l'antéflexion ; topographie radiculaire</td><td><span>Canal lombaire étroit</span>, arthrose lombaire</td></tr>\n        </tbody>\n      </table>\n      <p class=\"obj-renvois\"><em>📎 Items liés : 228 — Ulcère de la jambe</em></p><h4>Points de raisonnement et précautions</h4><ul><li>L’ischémie chronique menaçant le membre associe douleur de repos, ulcère ou <span class=\"nc-red_bg\">gangrène</span> et preuve d’artériopathie ; intégrer plaie et infection (classification WIfI). Un IPS peut être faussement rassurant si artères calcifiées ; mesurer la pression d’<span class=\"nc-yellow_bg\">orteil</span>.</li></ul></div><details><summary>Sources et compléments</summary><p>Relecture du 15 octobre 2026. Couleurs reprises des passages correspondants de ton cours Notion.</p><ul><li><a href=\"https://app.notion.com/p/2ad37f85d941812997bdd5a47ff348db?pvs=204\" target=\"_blank\" rel=\"noopener noreferrer\">Ton cours Notion · Artériopathie oblitérante des membres inférieurs</a></li><li><a href=\"https://www.sfcardio.fr/publication/chapitre-07-item-225-arteriopathie-de-laorte-des-arteres-viscerales-et-des-membres-inferieurs-anevrismes/\" target=\"_blank\" rel=\"noopener noreferrer\">CNEC · Item 225</a></li><li><a href=\"https://esvs.org/guidelines/\" target=\"_blank\" rel=\"noopener noreferrer\">ESVS · Recommandations vasculaires</a></li></ul><p>Les compléments ATLAS sont des synthèses pédagogiques ; les repères historiques et les recommandations plus récentes sont distingués lorsque nécessaire.</p></details>","frequence":11},{"id":"225-4","rang":"A","rubrique":"Examens complémentaires","titre":"Savoir prescrire les examens complémentaires de première intention","contenu":"<div class=\"notion-course\"><p>L'AOMI est <strong>évoquée cliniquement</strong> puis <strong>confirmée en 1ʳᵉ intention par la mesure des pressions</strong>. Après confirmation, un bilan évalue le handicap fonctionnel, la sévérité hémodynamique et la localisation des lésions.</p>\n\n      <h4 style=\"margin:14px 0 6px;font-size:14px;\"><span>Index de pression systolique</span> (IPS) — examen clé de 1ʳᵉ intention</h4>\n      <p>L'<span>IPS</span> est le rapport <span>PAS cheville / PAS bras</span>, mesuré au <span><span class=\"nc-blue_bg\">doppler</span></span> de poche. La pression de cheville retient la valeur la plus élevée entre artère tibiale postérieure et pédieuse.</p>\n      <table>\n        <thead>\n          <tr><th>Valeur d'<span>IPS</span></th><th>Interprétation</th></tr>\n        </thead>\n        <tbody>\n          <tr><td><span>1 - 1,40</span></td><td>Valeur normale</td></tr>\n          <tr><td><span>&lt; 0,90</span></td><td><span>AOMI</span> ; également marqueur de risque cardiovasculaire élevé</td></tr>\n          <tr><td><span>&lt; 0,70</span></td><td><span class=\"nc-red_bg\">AOMI sévère</span></td></tr>\n          <tr><td><span>&gt; 1,40</span></td><td><span><span class=\"nc-yellow_bg\">Médiacalcose</span></span> — rigidité artérielle (calcification de la média, <span class=\"nc-green nc-bold\">sans</span> <span class=\"nc-green nc-bold\">rétrécissement</span> <span class=\"nc-green nc-bold\">intraluminal</span>) ; fréquente chez le diabétique âgé, le dialysé, le grand âge</td></tr>\n        </tbody>\n      </table>\n      <div class=\"callout callout-warn\">\n        <strong>Si <span class=\"nc-yellow_bg\">médiacalcose</span> (<span><span class=\"nc-yellow_bg\">IPS</span></span><span class=\"nc-yellow_bg\"> &gt; 1,40</span>).</strong> La pression de cheville est ininterprétable : on la remplace par la <span>pression d'<span class=\"nc-yellow_bg\">orteil</span></span> — AOMI si index d'<span class=\"nc-yellow_bg\">orteil</span> <span>&lt; 0,70</span>, <span class=\"nc-red nc-bold\">ischémie critique</span> si <span class=\"nc-red_bg\">pression d'orteil </span><span><span class=\"nc-red_bg\">&lt; 30 mmHg</span></span>.\n      </div>\n\n      <h4 style=\"margin:14px 0 6px;font-size:14px;\">Autres examens de 1ʳᵉ intention</h4>\n      <table>\n        <thead>\n          <tr><th>Examen</th><th>Apport</th></tr>\n        </thead>\n        <tbody>\n          <tr><td><strong>Test de marche</strong> (tapis, protocole de <span class=\"nc-green_bg\">Strandness</span> : 3,2 km/h, pente <span>10 %</span>)</td><td><span>Sensibilise le diagnostic</span> : une baisse de PAS cheville <span>&gt; 30 mmHg</span> et/ou une <span class=\"nc-red nc-bold\">baisse </span><span><span class=\"nc-red nc-bold\">&gt; 20 % de l'IPS</span></span> après la marche est évocatrice d'AOMI. Confirme l'origine artérielle de la <span>claudication</span>.</td></tr>\n          <tr><td><strong>Écho-<span>Doppler artériel</span></strong></td><td><span><span class=\"nc-yellow_bg\">Examen de référence</span></span> pour localiser les lésions artérielles et leur retentissement hémodynamique ; recherche aussi un AAA.</td></tr>\n          <tr><td><strong><span>TcPO2</span></strong> (mesure transcutanée de la PO2)</td><td>Utile au diagnostic et à l'évaluation de l'<span><span class=\"nc-red nc-bold\">ischémie critique</span></span> (<span class=\"nc-green_bg\">sujet sain</span> <span class=\"nc-pink nc-bold\">&gt;</span><span><span class=\"nc-pink nc-bold\"> 50 mmHg</span></span> ; <span class=\"nc-orange_bg\">hypoxie continue</span> <span>10-35 mmHg</span> ; <span class=\"nc-red_bg\">hypoxie critique</span> <span>&lt; 10 mmHg</span>).</td></tr>\n          <tr><td><strong>Bilan <span>biologique</span> des <span>FRCV</span></strong></td><td>Recherche d'une <span>dyslipidémie</span>, d'un <span>diabète</span>, d'une <span>insuffisance rénale chronique</span>.</td></tr>\n        </tbody>\n      </table>\n\n      <h4 style=\"margin:14px 0 6px;font-size:14px;\">Examens de 2ᵈᵉ intention — uniquement si <span>revascularisation</span> envisagée</h4>\n      <table>\n        <thead>\n          <tr><th>Examen</th><th>Caractéristiques</th></tr>\n        </thead>\n        <tbody>\n          <tr><td><span>Angio-TDM</span></td><td>Imagerie non invasive performante (chenal circulant + paroi). Nécessite un <span>produit de contraste iodé</span> : vérifier <span>allergie</span>, fonction rénale, absence de <span>biguanides</span>.</td></tr>\n          <tr><td><span>Angio-IRM</span></td><td>En insuffisance rénale sévère, discuter le contraste et le type de produit avec le radiologue ; le risque dépend de la molécule et du contexte, ce n’est pas une interdiction uniforme de toute IRM.</td></tr>\n          <tr><td><span>Artériographie</span></td><td><span>Ponction</span> artérielle directe + injection de PDC. Surtout réservée aux procédures de <span>revascularisation</span> et au réseau jambier/pédieux.</td></tr>\n        </tbody>\n      </table>\n      <figure class=\"obj-figure\">\n        <img src=\"../assets/images/225/angio-arteres-membre-inferieur.png\" alt=\"Angiographie des artères du membre inférieur annotée : iliaque externe, fémorale commune, fémorale profonde et superficielle, poplitée, tibiales, fibulaire\" loading=\"lazy\">\n        <figcaption><span>Angiographie</span> des artères du membre inférieur (examen de 2ᵈᵉ intention) : visualisation simultanée de l'ensemble de l'arbre artériel pour identifier sténoses et occlusions. Source : fiche source EDN item 225.</figcaption>\n      </figure>\n      <p class=\"obj-renvois\"><em>📎 Items liés : 264 — <span>Insuffisance rénale chronique</span></em></p></div><details><summary>Sources et compléments</summary><p>Relecture du 15 octobre 2026. Couleurs reprises des passages correspondants de ton cours Notion.</p><ul><li><a href=\"https://app.notion.com/p/2ad37f85d941812997bdd5a47ff348db?pvs=204\" target=\"_blank\" rel=\"noopener noreferrer\">Ton cours Notion · Artériopathie oblitérante des membres inférieurs</a></li><li><a href=\"https://www.sfcardio.fr/publication/chapitre-07-item-225-arteriopathie-de-laorte-des-arteres-viscerales-et-des-membres-inferieurs-anevrismes/\" target=\"_blank\" rel=\"noopener noreferrer\">CNEC · Item 225</a></li><li><a href=\"https://esvs.org/guidelines/\" target=\"_blank\" rel=\"noopener noreferrer\">ESVS · Recommandations vasculaires</a></li></ul><p>Les compléments ATLAS sont des synthèses pédagogiques ; les repères historiques et les recommandations plus récentes sont distingués lorsque nécessaire.</p></details>","frequence":5},{"id":"225-5","rang":"A","rubrique":"Prise en charge","titre":"Connaître le traitement médical : traitement médicamenteux et principes du traitement chirurgical","contenu":"<div class=\"notion-course\"><p>Le traitement de l'AOMI est de <strong>deux ordres</strong> : à <span>visée générale</span> (améliorer le <span>pronostic</span> cardiovasculaire et vital) et à <span>visée locale</span> (résoudre les symptômes et améliorer le pronostic du membre).</p>\n\n      <h4 style=\"margin:14px 0 6px;font-size:14px;\">Mesures générales</h4>\n      <ul>\n        <li><strong>Prise en charge des <span>FRCV</span> :</strong> <span>arrêt du <span class=\"nc-red_bg\">tabac</span></span>, contrôle du <span><span class=\"nc-red_bg\">diabète</span></span>.</li>\n        <li><strong>Marche / réadaptation supervisée :</strong> <span><span class=\"nc-pink nc-bold\">30-45 minutes</span>, <span class=\"nc-pink nc-bold\">≥ 3 fois/semaine</span></span> ; favorise le développement de la circulation collatérale, l'état métabolique musculaire et l'allongement de la distance de marche.</li>\n        <li><strong>Soins de plaies :</strong> sous supervision d'une équipe multidisciplinaire spécialisée.</li>\n      </ul>\n\n      <h4 style=\"margin:14px 0 6px;font-size:14px;\">Traitement <span>médicamenteux</span></h4>\n      <table>\n        <thead>\n          <tr><th>Classe</th><th>Modalités</th></tr>\n        </thead>\n        <tbody>\n          <tr><td><span>Antiplaquettaire</span> (<span>aspirine</span>)</td><td>À dose antiagrégante (indication débattue si AOMI asymptomatique isolée).</td></tr>\n          <tr><td><span>Statine</span></td><td>Objectif <span>LDL <span class=\"nc-pink\">&lt; 0,55 g/L</span></span> et <span>réduction</span> <span>≥ 50 %</span> de la valeur initiale ; peut augmenter le <span>périmètre de marche</span>.</td></tr>\n          <tr><td><span>IEC</span></td><td>IEC/ARA2 selon indication cardiovasculaire, PA, fonction rénale et tolérance ; ne pas présenter un IEC comme obligatoire pour toute AOMI normotendue.</td></tr>\n          <tr><td><span>β-bloquants</span></td><td>Avec <span>prudence si <span class=\"nc-red nc-bold\">ischémie critique</span></span> non revascularisable ; possibles si indication formelle (cardiopathie <span>ischémique</span>, IC à FE altérée).</td></tr>\n          <tr><td><span>Prostaglandines</span></td><td>Proposées en cas d'ischémie critique non revascularisable (perfusions quotidiennes en milieu spécialisé).</td></tr>\n        </tbody>\n      </table>\n\n      <h4 style=\"margin:14px 0 6px;font-size:14px;\"><span>Revascularisation</span> — indications et principes</h4>\n      <p><strong>Indications :</strong> <span class=\"nc-brown_bg\">ischémie permanente</span> ; <span>claudication</span> intermittente sévère après traitement médical bien mené <span><span class=\"nc-red nc-bold\">&gt; 3-6 mois</span></span> ; <span>périmètre de marche</span> très faible (<span><span class=\"nc-red nc-bold\">&lt; 100 m</span></span>) avec handicap important ; <span class=\"nc-brown_bg\">atteintes aorto-iliaques sévères et extensives</span>.</p>\n      <table>\n        <thead>\n          <tr><th>Technique</th><th>Principes</th></tr>\n        </thead>\n        <tbody>\n          <tr><td><strong>Endovasculaire</strong></td><td>Meilleurs résultats sur lésions <span><span class=\"nc-green nc-bold\">courtes</span> et <span class=\"nc-green nc-bold\">proximales</span></span> : <span><span class=\"nc-pink nc-bold\">angioplastie</span></span><span class=\"nc-pink nc-bold\"> intraluminale par ballonnet</span> ± pose de <span><span class=\"nc-pink nc-bold\">stent</span></span> ; <span><span class=\"nc-pink nc-bold\">bithérapie antiplaquettaire</span> <span class=\"nc-pink nc-bold\">1-6 mois</span></span> selon le geste.</td></tr>\n          <tr><td><strong><span>Chirurgie</span></strong></td><td><span><span class=\"nc-pink nc-bold\">Pontage</span></span> essentiellement (aorto-bifémoral, fémoro-poplité, fémoro-jambier) ; <span class=\"nc-pink nc-bold\">geste d'</span><span><span class=\"nc-pink nc-bold\">endartériectomie</span></span> parfois associé.</td></tr>\n          <tr><td><strong><span>Surveillance</span></strong></td><td>Clinique + <span>écho-<span>Doppler</span></span> — risque de <span><span class=\"nc-red nc-bold\">thrombose de stent ou de pontage</span></span> et de dégradation des <span class=\"nc-red nc-bold\">anastomoses</span>.</td></tr>\n        </tbody>\n      </table>\n      <div class=\"callout callout-info\">\n        <strong>Amputation.</strong> Geste ultime, à défaut de toute possibilité de <span>revascularisation</span>. Réalisée en <span>zone saine et bien oxygénée</span> (intérêt de la <span>TcPO2</span>), en sauvegardant autant que possible l'appui et l'articulation du genou (appareillage par prothèse).\n      </div>\n      <p class=\"obj-renvois\"><em>📎 Items liés : 223 — <span>Dyslipidémie</span> · 224 — <span>HTA</span></em></p></div><details><summary>Sources et compléments</summary><p>Relecture du 15 octobre 2026. Couleurs reprises des passages correspondants de ton cours Notion.</p><ul><li><a href=\"https://app.notion.com/p/2ad37f85d941812997bdd5a47ff348db?pvs=204\" target=\"_blank\" rel=\"noopener noreferrer\">Ton cours Notion · Artériopathie oblitérante des membres inférieurs</a></li><li><a href=\"https://www.sfcardio.fr/publication/chapitre-07-item-225-arteriopathie-de-laorte-des-arteres-viscerales-et-des-membres-inferieurs-anevrismes/\" target=\"_blank\" rel=\"noopener noreferrer\">CNEC · Item 225</a></li><li><a href=\"https://esvs.org/guidelines/\" target=\"_blank\" rel=\"noopener noreferrer\">ESVS · Recommandations vasculaires</a></li></ul><p>Les compléments ATLAS sont des synthèses pédagogiques ; les repères historiques et les recommandations plus récentes sont distingués lorsque nécessaire.</p></details>","frequence":3},{"id":"225-6","rang":"A","rubrique":"Suivi et/ou pronostic","titre":"Connaître les complications et le pronostic : ischémie aigüe des membres inférieurs, morbimortalité cardiovasculaire","contenu":"<div class=\"notion-course\"><p><strong>Complication aiguë locale</strong> — l'<span>ischémie aiguë de membre</span> est la principale complication aiguë : elle peut survenir par thrombose in situ d'une <span>lésion</span> d'AOMI préexistante. Tableau, <span>classification</span> et traitement sont détaillés dans les objectifs <em>« <span>Diagnostic positif</span> »</em> et <em>« Identifier une <span>urgence</span> »</em> de l'<span>ischémie aiguë</span>.</p>\n\n      <h4 style=\"margin:14px 0 6px;font-size:14px;\">Morbimortalité cardiovasculaire</h4>\n      <p>L'AOMI est l'<span>expression locale d'une maladie systémique</span> : le <span>pronostic vital</span> est avant tout conditionné par les atteintes <span>coronariennes</span> et <span>cérébrovasculaires</span> associées, qui doivent être recherchées et orientées par la clinique. Un <span>IPS &lt; 0,90</span> est associé à un risque cardiovasculaire élevé (accident coronarien ou cérébral fatal ou non) — l'<span>IPS</span> est utilisé comme <span>marqueur de risque cardiovasculaire</span>.</p>\n      <table>\n        <thead>\n          <tr><th>Situation</th><th><span>Pronostic</span></th></tr>\n        </thead>\n        <tbody>\n          <tr><td><span>Claudication</span> intermittente</td><td>Espérance de vie réduite de <span><span class=\"nc-red nc-bold\">-10 ans</span></span></td></tr>\n          <tr><td>Ischémie d'effort</td><td>Le risque d’amputation est nettement plus élevé en ischémie chronique menaçant le membre qu’en simple claudication. Il dépend de la perfusion, des plaies, de l’infection et de la possibilité de revascularisation.</td></tr>\n          <tr><td><span class=\"nc-brown_bg\">Ischémie permanente</span> chronique</td><td><span>Mortalité</span> <span><span class=\"nc-pink_bg\">25 % à 1 an</span></span> et <span><span class=\"nc-pink_bg\">70 % à 5 ans</span></span></td></tr>\n          <tr><td>Risque d'amputation du membre inférieur</td><td>Le risque d’amputation est nettement plus élevé en ischémie chronique menaçant le membre qu’en simple claudication. Il dépend de la perfusion, des plaies, de l’infection et de la possibilité de revascularisation.</td></tr>\n        </tbody>\n      </table>\n      <p class=\"obj-renvois\"><em>📎 Items liés : 339 — <span>Syndrome coronarien</span> aiguë · 340 — <span>AVC</span></em></p></div><details><summary>Sources et compléments</summary><p>Relecture du 15 octobre 2026. Couleurs reprises des passages correspondants de ton cours Notion.</p><ul><li><a href=\"https://app.notion.com/p/2ad37f85d941812997bdd5a47ff348db?pvs=204\" target=\"_blank\" rel=\"noopener noreferrer\">Ton cours Notion · Artériopathie oblitérante des membres inférieurs</a></li><li><a href=\"https://www.sfcardio.fr/publication/chapitre-07-item-225-arteriopathie-de-laorte-des-arteres-viscerales-et-des-membres-inferieurs-anevrismes/\" target=\"_blank\" rel=\"noopener noreferrer\">CNEC · Item 225</a></li><li><a href=\"https://esvs.org/guidelines/\" target=\"_blank\" rel=\"noopener noreferrer\">ESVS · Recommandations vasculaires</a></li></ul><p>Les compléments ATLAS sont des synthèses pédagogiques ; les repères historiques et les recommandations plus récentes sont distingués lorsque nécessaire.</p></details>","frequence":1},{"id":"225-7","rang":"A","rubrique":"Diagnostic positif","titre":"Savoir définir et identifier les manifestations cliniques d’ischémie aiguë complète ou incomplète","contenu":"<div class=\"notion-course\"><p>L'<span>ischémie aiguë</span> correspond à une <strong><span class=\"nc-red_bg\">interruption brutale du flux artériel</span></strong><span class=\"nc-red_bg\"> d'un membre</span> entraînant une ischémie tissulaire, pouvant aboutir à une <span>nécrose</span>. C'est une <span>urgence absolue</span> : tout retard expose au risque d'amputation, voire de décès.</p>\n      <div class=\"callout callout-danger\">\n        <strong>Chronologie de la souffrance tissulaire.</strong> <span class=\"nc-yellow_bg\">Cellules nerveuses</span> : <span><span class=\"nc-pink nc-bold\">&lt; 2 h</span></span>. <span class=\"nc-yellow_bg\">Cellules musculaires</span> : <span><span class=\"nc-pink nc-bold\">6-8 h</span></span> (rhabdomyolyse, risque de <span><span class=\"nc-red nc-bold\">syndrome des loges</span></span>). <span><span class=\"nc-red_bg\">Nécrose</span></span><span class=\"nc-red_bg\"> cutanée</span> : à partir de <span><span class=\"nc-pink nc-bold\">24 h</span></span>.\n      </div>\n\n      <h4 style=\"margin:14px 0 6px;font-size:14px;\"><span>Classification</span> de Rutherford</h4>\n      <table>\n        <thead>\n          <tr><th><span>Grade</span></th><th><span>Déficit sensitif</span></th><th><span>Déficit moteur</span></th><th><span>Pronostic</span></th></tr>\n        </thead>\n        <tbody>\n          <tr><td><strong>I</strong> — viable</td><td>Absent</td><td>Absent</td><td>Pas de <span>menace</span> immédiate, <span>urgence</span> relative</td></tr>\n          <tr><td><strong>IIa</strong> — discrètement menaçante</td><td>Absent ou limité aux orteils</td><td>Absent</td><td>Récupérable si prise en charge</td></tr>\n          <tr><td><strong>IIb</strong> — immédiatement menaçante</td><td>Présent au-delà des orteils</td><td>Modéré</td><td>Récupération possible si PEC immédiate</td></tr>\n          <tr><td><strong>III</strong> — irréversible</td><td>Anesthésie importante</td><td>Important, <span>paralysie</span></td><td>Perte tissulaire et déficit séquellaire inévitables</td></tr>\n        </tbody>\n      </table>\n\n      <h4 style=\"margin:14px 0 6px;font-size:14px;\">Tableau clinique</h4>\n      <ul>\n        <li><strong>Signes fonctionnels :</strong> <span>douleur spontanée brutale</span> à type de <span><span class=\"nc-red nc-bold\">broiement</span></span>, impotence fonctionnelle du membre.</li>\n        <li><strong>Signes physiques :</strong> membre <span><span class=\"nc-blue_bg\">froid</span>, <span class=\"nc-blue_bg\">pâle</span>, <span class=\"nc-blue_bg\">livide</span></span> ; <span><span class=\"nc-blue_bg\">abolition des pouls en aval</span></span><span class=\"nc-blue_bg\"> de l'occlusion</span> (estime la topographie).</li>\n      </ul>\n      <div class=\"callout callout-danger\">\n        <strong>Ischémie complète <span>vs</span> incomplète — point clé.</strong> La <span>paralysie signe l'ischémie complète</span> (gravité majeure) : impossibilité de <span class=\"nc-red nc-bold\">mobiliser les orteils</span>, de <span class=\"nc-red nc-bold\">relever le pied</span> (nerf fibulaire commun). <strong><span class=\"nc-green nc-bold\">Son absence définit l'ischémie incomplète</span>.</strong> Autres <span>signes de gravité</span> : <span class=\"nc-red_bg\">douleur à la palpation des masses musculaires</span>, hypoesthésie évoluant vers l'anesthésie cutanée. <span>Ischémie dépassée</span> (amputation d'emblée) : <span><span class=\"nc-red nc-bold\">rigidité musculaire</span></span>, <span><span class=\"nc-red nc-bold\">marbrures</span></span>, <span><span class=\"nc-red nc-bold\">phlyctènes</span></span>.\n      </div>\n      <p>Dans le cas le plus grave, l'<span><span class=\"nc-red nc-bold\">occlusion de la bifurcation aortique</span></span> entraîne une <span class=\"nc-red_bg\">ischémie bilatérale sévère</span> avec <span class=\"nc-red_bg\">paralysie sensitivomotrice</span> et <span class=\"nc-red_bg\">signes généraux</span> au premier plan (collapsus cardiovasculaire).</p>\n      <p><strong>Paraclinique</strong> — le <span>diagnostic est clinique</span> ; les examens ne doivent pas retarder la <span>revascularisation</span>. <span><span class=\"nc-blue_bg\">ECG</span></span> systématique à visée étiologique ; <span>écho-<span>Doppler</span></span> possible sans perte de temps si <span>grade</span> I sans atteinte neurologique ; <span><span class=\"nc-blue_bg\">artériographie</span></span> le plus souvent réalisée au bloc opératoire.</p></div><details><summary>Sources et compléments</summary><p>Relecture du 15 octobre 2026. Couleurs reprises des passages correspondants de ton cours Notion.</p><ul><li><a href=\"https://app.notion.com/p/2ad37f85d941817f97e6d6db1200f40e?pvs=204\" target=\"_blank\" rel=\"noopener noreferrer\">Ton cours Notion · Ischémie aiguë des membres inférieurs</a></li><li><a href=\"https://www.sfcardio.fr/publication/chapitre-07-item-225-arteriopathie-de-laorte-des-arteres-viscerales-et-des-membres-inferieurs-anevrismes/\" target=\"_blank\" rel=\"noopener noreferrer\">CNEC · Item 225</a></li><li><a href=\"https://esvs.org/guidelines/\" target=\"_blank\" rel=\"noopener noreferrer\">ESVS · Recommandations vasculaires</a></li></ul><p>Les compléments ATLAS sont des synthèses pédagogiques ; les repères historiques et les recommandations plus récentes sont distingués lorsque nécessaire.</p></details>","frequence":4},{"id":"225-8","rang":"B","rubrique":"Etiologies","titre":"Connaître les autres causes de l’ischémie aiguë","contenu":"<div class=\"notion-course\"><p>Deux grands mécanismes sont à distinguer : la <span>thrombose artérielle in situ</span> et l'<span>embolie sur artères saines</span>.</p>\n      <table>\n        <thead>\n          <tr><th></th><th>Thrombose artérielle in situ</th><th>Embolie sur artères saines</th></tr>\n        </thead>\n        <tbody>\n          <tr><td><span>Terrain</span></td><td>Sujet âgé à <span>FRCV</span> (voire AOMI préexistante)</td><td>Sujet jeune sans ATCD vasculaire, mais pouvant avoir une cardiopathie</td></tr>\n          <tr><td>Douleur</td><td>Intensité moyenne, survenue progressive (<span class=\"nc-green_bg\">collatéralité</span> préexistante)</td><td><span><span class=\"nc-red_bg\">Très brutale</span>, <span class=\"nc-red_bg\">aiguë</span> et <span class=\"nc-red_bg\">sévère</span></span> (<span class=\"nc-red_bg\">absence de collatérales</span>) ; peut suivre des <span><span class=\"nc-blue_bg\">palpitations</span></span></td></tr>\n        </tbody>\n      </table>\n      <h4 style=\"margin:14px 0 6px;font-size:14px;\">Étiologies de la thrombose in situ</h4>\n      <ul>\n        <li><strong>Sur artères pathologiques :</strong> <span><span class=\"nc-red_bg\">AOMI</span></span> ++++ ; artériopathies non athéromateuses ; anévrisme poplité thrombosé ; <span>dissection</span> <span class=\"nc-brown_bg nc-bold\">aorto</span>-<span class=\"nc-brown_bg nc-bold\">iliaque</span>.</li>\n        <li><strong>Sur artères saines :</strong> <span>déshydratation</span> / hémoconcentration ; kyste adventiciel ; thrombophlébite <span>ischémique</span> ; <span>coagulopathies</span> et thrombophilies ; <span>thrombopénie induite par l'héparine</span> ; <span>SAPL</span>.</li>\n      </ul>\n      <h4 style=\"margin:14px 0 6px;font-size:14px;\">Étiologies de l'embolie</h4>\n      <ul>\n        <li><strong>Causes cardiaques :</strong> <span>fibrillation atriale</span> +++ ; <span class=\"nc-red_bg\">valvulopathies</span> ; foramen ovale perméable, anévrisme du septum interatrial ; <span>IDM</span>, dyskinésie ou anévrisme du VG ; tumeurs cardiaques (myxome de l'atrium).</li>\n        <li><strong>Atteintes aortiques :</strong> <span>athérome</span>, anévrisme, aortite, tumeurs aortiques.</li>\n      </ul>\n      <div class=\"callout callout-warn\">\n        <strong>Nuance.</strong> Ces deux tableaux ne sont pas toujours distincts : une embolie peut survenir sur des artères déjà atteintes par l'<span class=\"nc-red_bg\">AOMI</span>, et une thrombose in situ peut survenir sur la <span>rupture</span> d'une <span>plaque</span> initialement non occlusive, sans signe préalable d'<span class=\"nc-red_bg\">AOMI</span>.\n      </div>\n      <p class=\"obj-renvois\"><em>📎 Items liés : 232 — <span>Fibrillation atriale</span></em></p></div><details><summary>Sources et compléments</summary><p>Relecture du 15 octobre 2026. Couleurs reprises des passages correspondants de ton cours Notion.</p><ul><li><a href=\"https://app.notion.com/p/2ad37f85d941817f97e6d6db1200f40e?pvs=204\" target=\"_blank\" rel=\"noopener noreferrer\">Ton cours Notion · Ischémie aiguë des membres inférieurs</a></li><li><a href=\"https://www.sfcardio.fr/publication/chapitre-07-item-225-arteriopathie-de-laorte-des-arteres-viscerales-et-des-membres-inferieurs-anevrismes/\" target=\"_blank\" rel=\"noopener noreferrer\">CNEC · Item 225</a></li><li><a href=\"https://esvs.org/guidelines/\" target=\"_blank\" rel=\"noopener noreferrer\">ESVS · Recommandations vasculaires</a></li></ul><p>Les compléments ATLAS sont des synthèses pédagogiques ; les repères historiques et les recommandations plus récentes sont distingués lorsque nécessaire.</p></details>","frequence":0},{"id":"225-9","rang":"A","rubrique":"Identifier une urgence","titre":"Connaître les principes d’un traitement en urgence","contenu":"<div class=\"notion-course\"><ul><li>Appel vasculaire immédiat, évaluation de la viabilité du membre et de l’état général. Une atteinte motrice signe une menace immédiate ; ne pas attendre un délai théorique de six heures pour agir.</li><li><span class=\"nc-pink_bg\">HNF</span> IV dès le diagnostic sauf contre-indication, avec surveillance selon le protocole, antalgie, voie veineuse et bilan préopératoire. Protéger le membre, éviter compression, lésions cutanées et chaleur directe ; oxygène si hypoxémie.</li><li>Rutherford I : membre viable, imagerie urgente permettant de planifier le traitement. IIa : menace marginale sans déficit moteur, revascularisation urgente ; une thrombolyse dirigée peut être discutée. IIb : déficit moteur, revascularisation immédiate ; aucune imagerie ou thrombolyse lente ne doit retarder le sauvetage.</li><li>Grade III : anesthésie profonde, paralysie/rigidité et lésions irréversibles ; amputation primaire habituellement indiquée après évaluation spécialisée. La revascularisation d’un membre non viable expose à une reperfusion dangereuse.</li><li>Technique adaptée à l’anatomie et à la cause : thrombectomie/embolectomie, chirurgie de reconstruction, traitement endovasculaire ou stratégie hybride.</li><li>Après reperfusion : surveiller <span class=\"nc-red nc-bold\">syndrome des loges</span>, potassium, ECG, fonction rénale, <span class=\"nc-blue_bg\">CPK</span>, acidose et <span class=\"nc-blue_bg\">diurèse</span>. Aponévrotomie si <span class=\"nc-red nc-bold\">syndrome des loges</span> ou selon le risque. Une <span class=\"nc-orange_bg\">hyperkaliémie</span> menaçante nécessite le protocole d’urgence (protection myocardique si indiquée, transfert intracellulaire et élimination) ; un chélateur seul ne suffit pas. Bicarbonates et épuration sont discutés selon les anomalies, non systématiques.</li><li>Bilan étiologique et prévention secondaire : source embolique (FA, thrombus intracardiaque), thrombose sur <span class=\"nc-red_bg\">AOMI</span> ou anévrisme ; traitement antithrombotique et vasculaire adapté.</li></ul><figure class=\"obj-figure\">\n        <img src=\"../assets/images/225/algorithme-ischemie-aigue.png\" alt=\"Algorithme de prise en charge de l&#x27;ischémie aiguë de membre selon le grade : viable (grade I), viable avec déficit sensitif (grade II), irréversible (grade III)\" loading=\"lazy\">\n        <figcaption>Algorithme de prise en charge de l'<span>ischémie aiguë</span> de membre : <span>héparine</span> + <span>antalgiques</span> d'emblée, puis orientation selon le <span>grade</span> — imagerie ou revascularisation en <span>urgence</span> (I-II), amputation (III). Source : fiche source EDN item 225.</figcaption>\n      </figure></div><details><summary>Sources et compléments</summary><p>Relecture du 15 octobre 2026. Couleurs reprises des passages correspondants de ton cours Notion.</p><ul><li><a href=\"https://app.notion.com/p/2ad37f85d941817f97e6d6db1200f40e?pvs=204\" target=\"_blank\" rel=\"noopener noreferrer\">Ton cours Notion · Ischémie aiguë des membres inférieurs</a></li><li><a href=\"https://www.sfcardio.fr/publication/chapitre-07-item-225-arteriopathie-de-laorte-des-arteres-viscerales-et-des-membres-inferieurs-anevrismes/\" target=\"_blank\" rel=\"noopener noreferrer\">CNEC · Item 225</a></li><li><a href=\"https://esvs.org/guidelines/\" target=\"_blank\" rel=\"noopener noreferrer\">ESVS · Recommandations vasculaires</a></li></ul><p>Les compléments ATLAS sont des synthèses pédagogiques ; les repères historiques et les recommandations plus récentes sont distingués lorsque nécessaire.</p></details><p><a class=\"btn secondary small\" href=\"#item/225/algorithmes/college-cardio-225-ischemie\">Ouvrir la transcription interactive du schéma →</a></p>","frequence":1},{"id":"225-10","rang":"A","rubrique":"Définition","titre":"Connaître la définition et l’histoire naturelle d’un anévrisme de l’aorte abdominale et savoir rechercher d’autres localisations anévrismales","contenu":"<div class=\"notion-course\"><p>Un <span>anévrisme artériel</span> est une <strong>dilatation focale et permanente</strong> d'une artère, avec <span class=\"nc-yellow_bg\">perte du parallélisme de ses parois</span>, dont le <span>diamètre</span> est <span>&gt; 1,5 ×</span> le diamètre d'amont. La dilatation peut être <span>fusiforme</span> ou <span>sacciforme</span>. Diamètre normal de l'aorte abdominale : <span><span class=\"nc-green_bg\">18-20 mm</span></span> chez l'homme, <span><span class=\"nc-green_bg\">14-16 mm</span></span> chez la femme.</p>\n      <div class=\"callout callout-info\">\n        <strong>Définition <span>HAS</span> de l'AAA.</strong> Soit un <span>diamètre</span> antéro-postérieur <span><span class=\"nc-pink nc-bold\">&gt; 30 mm</span></span>, soit une dilatation <span>≥ + 50 %</span> par rapport au diamètre de l'aorte abdominale sus-jacente normale.\n      </div>\n\n      <h4 style=\"margin:14px 0 6px;font-size:14px;\">Histoire naturelle — <span class=\"nc-brown_bg\">croissance</span> et risque évolutif</h4>\n      <ul>\n        <li><strong>Croissance :</strong> en moyenne <span>2-4 mm/an</span> ; <span>non linéaire</span> chez un même patient et variable d'un patient à l'autre ; d'autant <strong><span class=\"nc-red nc-bold\">plus rapide</span> que le <span>diamètre</span> est grand</strong>. AAA dit « à croissance rapide » si <span><span class=\"nc-red nc-bold\">&gt; 1 cm/an</span></span> (indication chirurgicale).</li>\n        <li><strong>Risque évolutif = la <span>rupture</span></strong> ; ce risque augmente avec le <span>diamètre</span> : <span>&lt; 0,5 %/an</span> si diamètre <span class=\"nc-pink nc-bold\">&lt;</span><span><span class=\"nc-pink nc-bold\"> 40 mm</span></span>, puis croissant. Le risque est <span><span class=\"nc-red nc-bold\">majoré chez la femme à diamètre égal</span></span> (× 4).</li>\n      </ul>\n\n      <h4 style=\"margin:14px 0 6px;font-size:14px;\">Localisations — rechercher d'autres anévrismes</h4>\n      <p>L'aorte abdominale est la localisation la plus fréquente, surtout dans le <span class=\"nc-pink_bg\">segment </span><span><span class=\"nc-pink_bg\">sous-rénal</span></span>. La découverte d'un AAA justifie la recherche systématique d'autres localisations :</p>\n      <table>\n        <thead>\n          <tr><th>Localisation à rechercher</th><th>Modalité</th></tr>\n        </thead>\n        <tbody>\n          <tr><td>Rechercher un <span class=\"nc-orange_bg\">anévrisme poplité</span> chez un porteur d’AAA ; ne pas inverser les fréquences d’association AAA–<span class=\"nc-orange_bg\">anévrisme poplité</span>.</td><td><span><span class=\"nc-blue_bg\">Écho-</span><span><span class=\"nc-blue_bg\">Doppler</span></span></span><span class=\"nc-blue_bg\"> des artères des membres inférieurs</span></td></tr>\n          <tr><td><span class=\"nc-orange_bg\">Anévrisme des artères iliaques</span></td><td><span><span class=\"nc-blue_bg\">Écho-</span><span><span class=\"nc-blue_bg\">Doppler</span></span></span><span class=\"nc-blue_bg\"> ou </span><span><span class=\"nc-blue_bg\">angio-</span><span><span class=\"nc-blue_bg\">TDM</span></span></span></td></tr>\n          <tr><td><span class=\"nc-orange_bg\">Anévrisme de l'aorte thoracique</span></td><td><span>Angio-<span>TDM</span></span> thoraco-abdomino-pelvienne</td></tr>\n          <tr><td><span>Dépistage</span> de l'<span>athérosclérose</span></td><td>En particulier <span><span class=\"nc-red nc-bold\">coronaires</span></span> et <span>troncs supra-aortiques</span></td></tr>\n        </tbody>\n      </table></div><details><summary>Sources et compléments</summary><p>Relecture du 15 octobre 2026. Couleurs reprises des passages correspondants de ton cours Notion.</p><ul><li><a href=\"https://app.notion.com/p/2ad37f85d941815193ddc58435a90f95?pvs=204\" target=\"_blank\" rel=\"noopener noreferrer\">Ton cours Notion · Anévrisme de l&#x27;aorte abdominale</a></li><li><a href=\"https://www.sfcardio.fr/publication/chapitre-07-item-225-arteriopathie-de-laorte-des-arteres-viscerales-et-des-membres-inferieurs-anevrismes/\" target=\"_blank\" rel=\"noopener noreferrer\">CNEC · Item 225</a></li><li><a href=\"https://esvs.org/guidelines/\" target=\"_blank\" rel=\"noopener noreferrer\">ESVS · Recommandations vasculaires</a></li></ul><p>Les compléments ATLAS sont des synthèses pédagogiques ; les repères historiques et les recommandations plus récentes sont distingués lorsque nécessaire.</p></details>","frequence":0},{"id":"225-11","rang":"B","rubrique":"Etiologies","titre":"Connaître les principales étiologies des anévrismes de l’aorte abdominale et les principes du dépistage","contenu":"<div class=\"notion-course\"><ul><li>Les facteurs majeurs d’AAA sont âge, sexe <span class=\"nc-red_bg\">masculin</span>, <span class=\"nc-red_bg\">tabagisme</span> et antécédents familiaux. Le mécanisme comporte une dégradation de la matrice pariétale ; l’association à l’athérome ne signifie pas que l’AAA est une simple plaque dilatée.</li><li>Le diabète est associé dans les études à une moindre fréquence/croissance des AAA, sans constituer une protection clinique à rechercher. Le mécanisme ne se résume pas à la médiacalcose.</li><li>Autres causes ou contextes : maladie inflammatoire/infectieuse, maladie du tissu conjonctif, évolution après <span class=\"nc-red\">dissection</span> ; distinguer anévrisme vrai et faux anévrisme.</li><li><span class=\"nc-yellow_bg nc-bold\">Dépistage</span> ciblé par échographie : repère HAS, <span class=\"nc-red nc-bold\">hommes</span> de 65 à 75 ans fumeurs ou anciens fumeurs, et <span class=\"nc-red nc-bold\">hommes</span> de 50 à 75 ans avec antécédent familial d’AAA. D’autres recommandations proposent des populations plus larges : préciser la source plutôt que présenter tous les adultes de 60 à 85 ans comme une indication universelle.</li><li>Un anévrisme découvert justifie de rechercher d’autres localisations selon le contexte (notamment iliaques et poplitées) et d’évaluer les facteurs cardiovasculaires.</li></ul></div><details><summary>Sources et compléments</summary><p>Relecture du 15 octobre 2026. Couleurs reprises des passages correspondants de ton cours Notion.</p><ul><li><a href=\"https://app.notion.com/p/2ad37f85d941815193ddc58435a90f95?pvs=204\" target=\"_blank\" rel=\"noopener noreferrer\">Ton cours Notion · Anévrisme de l&#x27;aorte abdominale</a></li><li><a href=\"https://www.sfcardio.fr/publication/chapitre-07-item-225-arteriopathie-de-laorte-des-arteres-viscerales-et-des-membres-inferieurs-anevrismes/\" target=\"_blank\" rel=\"noopener noreferrer\">CNEC · Item 225</a></li><li><a href=\"https://esvs.org/guidelines/\" target=\"_blank\" rel=\"noopener noreferrer\">ESVS · Recommandations vasculaires</a></li><li><a href=\"https://www.has-sante.fr/jcms/c_1361253/en/anevrismes-de-l-aorte-abdominale-en-france-proposer-un-depistage-cible-opportuniste-unique-chez-les-hommes-presentant-des-facteurs-de-risque\" target=\"_blank\" rel=\"noopener noreferrer\">HAS · Dépistage ciblé de l’AAA</a></li></ul><p>Les compléments ATLAS sont des synthèses pédagogiques ; les repères historiques et les recommandations plus récentes sont distingués lorsque nécessaire.</p></details>","frequence":2},{"id":"225-12","rang":"A","rubrique":"Diagnostic positif","titre":"Connaître les signes cliniques des anévrismes de l’aorte","contenu":"<div class=\"notion-course\"><h4 style=\"margin:4px 0 6px;font-size:14px;\">Forme asymptomatique (la plus fréquente)</h4>\n      <p>Découverte le plus souvent <strong>fortuite</strong> : <span>masse abdominale battante et expansive</span> de la région para-ombilicale, <span class=\"nc-blue_bg\">avec ou sans souffle</span> (palpable surtout chez les sujets maigres ou si l'anévrisme est volumineux), ou découverte d'imagerie (<span>échographie</span>, <span>TDM</span>, <span>IRM</span>).</p>\n      <div class=\"callout callout-info\">\n        <strong>Signe de Bakey.</strong> Possibilité de glisser la main entre le pôle supérieur de l'anévrisme et les côtes du patient — en faveur d'un anévrisme <span>sous-rénal</span>.\n      </div>\n\n      <h4 style=\"margin:14px 0 6px;font-size:14px;\">Formes symptomatiques (complications)</h4>\n      <table>\n        <thead>\n          <tr><th>Complication</th><th>Traduction clinique</th></tr>\n        </thead>\n        <tbody>\n          <tr><td><span><span class=\"nc-red nc-bold\">Fissuration</span> / <span class=\"nc-red nc-bold\">rupture</span></span></td><td><span><span class=\"nc-blue_bg\">Douleur abdominale</span></span><span class=\"nc-blue_bg\"> ou lombaire</span> ± tableau de <span>choc hémorragique</span> ; <span><span class=\"nc-red nc-bold\">rupture</span></span> rétropéritonéale (syndrome fissuraire) ou intrapéritonéale (foudroyante).</td></tr>\n          <tr><td>Fistules</td><td><strong><span><span class=\"nc-red nc-bold\">Fistule</span></span> aorto-cave :</strong> <span><span class=\"nc-red_bg\">insuffisance cardiaque</span></span><span class=\"nc-red_bg\"> à débit élevé</span>.<br><strong><span class=\"nc-red nc-bold\">Fistule</span> aorto-digestive :</strong> <span class=\"nc-red_bg\">hémorragie digestive</span> (<span>hématémèse</span>, <span>rectorragie</span>).</td></tr>\n          <tr><td>Complication <span>embolique</span></td><td>À partir du <span>thrombus</span> intra-anévrismal : <span class=\"nc-red nc-bold\">occlusion artérielle aiguë du membre inférieur</span>, <span class=\"nc-red nc-bold\">embolies de cristaux de </span><span><span class=\"nc-red nc-bold\">cholestérol</span></span> (<span>orteil bleu</span>).</td></tr>\n          <tr><td>Compression d'organes</td><td><strong>Duodénum :</strong> <span>vomissements</span> post-prandiaux ; <strong>nerfs :</strong> radiculalgies ; <strong>VCI :</strong> <span>œdèmes</span> des MI ; <strong>os :</strong> érosions vertébrales ; <strong>voies urinaires :</strong> coliques néphrétiques.</td></tr>\n          <tr><td><span class=\"nc-yellow_bg\">Anévrisme </span><span><span class=\"nc-yellow_bg\">inflammatoire</span></span></td><td>Gangue <span>inflammatoire</span> péri-anévrismale : <span>fièvre</span>, <span>AEG</span>, <span>syndrome inflammatoire</span> <span>biologique</span> (<span>VS</span>, <span>CRP</span>).</td></tr>\n        </tbody>\n      </table></div><details><summary>Sources et compléments</summary><p>Relecture du 15 octobre 2026. Couleurs reprises des passages correspondants de ton cours Notion.</p><ul><li><a href=\"https://app.notion.com/p/2ad37f85d941815193ddc58435a90f95?pvs=204\" target=\"_blank\" rel=\"noopener noreferrer\">Ton cours Notion · Anévrisme de l&#x27;aorte abdominale</a></li><li><a href=\"https://www.sfcardio.fr/publication/chapitre-07-item-225-arteriopathie-de-laorte-des-arteres-viscerales-et-des-membres-inferieurs-anevrismes/\" target=\"_blank\" rel=\"noopener noreferrer\">CNEC · Item 225</a></li><li><a href=\"https://esvs.org/guidelines/\" target=\"_blank\" rel=\"noopener noreferrer\">ESVS · Recommandations vasculaires</a></li></ul><p>Les compléments ATLAS sont des synthèses pédagogiques ; les repères historiques et les recommandations plus récentes sont distingués lorsque nécessaire.</p></details>","frequence":0},{"id":"225-13","rang":"A","rubrique":"Examens complémentaires","titre":"Savoir comment faire le diagnostic des anévrysmes de l’aorte abdominale","contenu":"<div class=\"notion-course\"><table>\n        <thead>\n          <tr><th>Examen</th><th>Place et apport</th></tr>\n        </thead>\n        <tbody>\n          <tr><td><span>Échographie abdominale</span></td><td><span class=\"nc-yellow_bg\">Examen de</span> <strong><span><span class=\"nc-yellow_bg nc-bold\">dépistage</span></span></strong> <span class=\"nc-yellow_bg\">et de</span> <strong><span><span class=\"nc-yellow_bg nc-bold\">suivi</span></span></strong><span class=\"nc-yellow_bg nc-bold\"> des AAA asymptomatiques</span> : donne le <span>diamètre</span> maximal et permet la <span>surveillance</span> de la croissance ; <span>échographie</span> annuelle après <span>chirurgie</span> conventionnelle.</td></tr>\n          <tr><td><span>TDM thoraco-abdomino-pelvienne injectée</span></td><td><strong>Examen pré-thérapeutique de référence.</strong> Indiquée <span><span class=\"nc-red nc-bold\">en urgence en cas d'AAA douloureux ou de suspicion de rupture</span></span>. Précise les diamètres et l'extension par rapport aux artères rénales et iliaques.</td></tr>\n          <tr><td><span>IRM</span></td><td>Peut remplacer l'<span>angio-<span>TDM</span></span> en cas de <span>contre-indication</span>.</td></tr>\n          <tr><td><span>Artériographie</span></td><td>N'a <strong>plus d'indication diagnostique</strong> : ne révèle que la lumière artérielle, mesure non fiable du <span>diamètre</span> à cause du <span>thrombus</span> mural fréquent.</td></tr>\n        </tbody>\n      </table>\n      <div class=\"callout callout-warn\">\n        <strong>Piège <span>TDM</span>.</strong> La longueur de l'AAA <span class=\"nc-brown_bg\">et la</span> présence d'un <span>thrombus</span> endoluminal <span>ne modifient pas la prise en charge</span> — seul le <span>diamètre</span> maximal compte.\n      </div>\n      <figure class=\"obj-figure\">\n        <img src=\"../assets/images/225/tdm-aaa-coupe-axiale.png\" alt=\"TDM abdominale en coupe axiale montrant un anévrisme de l&#x27;aorte abdominale sous-rénale\" loading=\"lazy\">\n        <figcaption><span>TDM</span> abdominale, coupe axiale : anévrisme de l'aorte abdominale sous-rénale — dilatation focale de l'aorte. Source : fiche source EDN item 225.</figcaption>\n      </figure>\n      <figure class=\"obj-figure\">\n        <img src=\"../assets/images/225/tdm-aaa-thrombus.png\" alt=\"TDM abdominale d&#x27;un anévrisme de l&#x27;aorte abdominale avec thrombus mural périphérique et chenal circulant central\" loading=\"lazy\">\n        <figcaption><span>TDM</span> abdominale : AAA avec thrombus mural périphérique (hypodense) et chenal circulant central rehaussé après injection. Source : fiche source EDN item 225.</figcaption>\n      </figure>\n      <p>Rechercher un <span class=\"nc-orange_bg\">anévrisme poplité</span> chez un porteur d’AAA ; ne pas inverser les fréquences d’association AAA–<span class=\"nc-orange_bg\">anévrisme poplité</span>.</p></div><details><summary>Sources et compléments</summary><p>Relecture du 15 octobre 2026. Couleurs reprises des passages correspondants de ton cours Notion.</p><ul><li><a href=\"https://app.notion.com/p/2ad37f85d941815193ddc58435a90f95?pvs=204\" target=\"_blank\" rel=\"noopener noreferrer\">Ton cours Notion · Anévrisme de l&#x27;aorte abdominale</a></li><li><a href=\"https://www.sfcardio.fr/publication/chapitre-07-item-225-arteriopathie-de-laorte-des-arteres-viscerales-et-des-membres-inferieurs-anevrismes/\" target=\"_blank\" rel=\"noopener noreferrer\">CNEC · Item 225</a></li><li><a href=\"https://esvs.org/guidelines/\" target=\"_blank\" rel=\"noopener noreferrer\">ESVS · Recommandations vasculaires</a></li></ul><p>Les compléments ATLAS sont des synthèses pédagogiques ; les repères historiques et les recommandations plus récentes sont distingués lorsque nécessaire.</p></details>","frequence":1},{"id":"225-14","rang":"B","rubrique":"Prise en charge","titre":"Connaître les principes thérapeutiques d’un anévrisme de l’aorte abdominale","contenu":"<div class=\"notion-course\"><ul><li>Contrôler les facteurs cardiovasculaires, surtout arrêter le tabac ; aucun médicament n’a démontré une capacité suffisante à faire disparaître un AAA et à remplacer sa surveillance.</li><li>AAA asymptomatique : suivi échographique adapté au diamètre, au sexe et à la croissance, avec avis vasculaire. Ne pas utiliser un calendrier unique indépendant du diamètre.</li><li>Repères d’intervention élective : diamètre ≥ 55 mm chez l’homme ; discussion autour de <span class=\"nc-pink nc-bold\">50 mm</span> chez la femme, en tenant compte du risque opératoire <span class=\"nc-yellow_bg\">et de</span> l’anatomie. Une <span class=\"nc-brown_bg\">croissance</span> rapide (environ ≥ 10 mm/an, à confirmer par une mesure fiable), une morphologie particulière ou des symptômes modifient la décision.</li><li>AAA douloureux ou compliqué : évaluation urgente, indépendamment du seuil de diamètre.</li><li>Chirurgie ouverte : mise à plat-greffe ; EVAR : exclusion par endoprothèse. Choix selon anatomie, espérance de vie, risque opératoire et préférence, avec explication des réinterventions possibles.</li><li>Après EVAR, surveillance durable des endofuites, de la taille du sac, de la <span class=\"nc-red nc-bold\">migration</span> et des jambages. Après chirurgie ouverte, surveillance de la prothèse et des anastomoses selon protocole ; aucun traitement ne dispense du suivi.</li></ul></div><details><summary>Sources et compléments</summary><p>Relecture du 15 octobre 2026. Couleurs reprises des passages correspondants de ton cours Notion.</p><ul><li><a href=\"https://app.notion.com/p/2ad37f85d941815193ddc58435a90f95?pvs=204\" target=\"_blank\" rel=\"noopener noreferrer\">Ton cours Notion · Anévrisme de l&#x27;aorte abdominale</a></li><li><a href=\"https://www.sfcardio.fr/publication/chapitre-07-item-225-arteriopathie-de-laorte-des-arteres-viscerales-et-des-membres-inferieurs-anevrismes/\" target=\"_blank\" rel=\"noopener noreferrer\">CNEC · Item 225</a></li><li><a href=\"https://esvs.org/guidelines/\" target=\"_blank\" rel=\"noopener noreferrer\">ESVS · Recommandations vasculaires</a></li></ul><p>Les compléments ATLAS sont des synthèses pédagogiques ; les repères historiques et les recommandations plus récentes sont distingués lorsque nécessaire.</p></details>","frequence":1},{"id":"225-15","rang":"A","rubrique":"Identifier une urgence","titre":"Savoir reconnaître et prendre en charge une situation d’urgence chez les patient porteur d’un anévrisme de l’aorte abdominale","contenu":"<div class=\"notion-course\"><div class=\"callout callout-danger\">\n        <strong>AAA rompu — <span>urgence</span> extrême.</strong> Taux de <span>mortalité</span> globale <span>&gt; 80 %</span>. Orientation immédiate vers un centre spécialisé de <span>chirurgie</span> vasculaire. Une <span><span class=\"nc-blue_bg\">TDM</span></span><span class=\"nc-blue_bg\"> peut être réalisée si l'état hémodynamique le permet</span> — mais <strong>aucune imagerie ne doit retarder l'intervention chez un patient en <span>choc</span> <span>hémorragique</span></strong>. Si les mesures de <span>réanimation</span> ne stabilisent pas le patient : passage direct au bloc.\n      </div>\n      <table>\n        <thead>\n          <tr><th>Situation d'urgence</th><th>Conduite à tenir</th></tr>\n        </thead>\n        <tbody>\n          <tr><td><span>AAA douloureux</span></td><td><span><span class=\"nc-blue_bg\">TDM</span></span><span class=\"nc-blue_bg\"> en </span><span><span class=\"nc-blue_bg\">urgence</span></span> + prise en charge de l'état général, cardiovasculaire, rénal et respiratoire ; <span>hospitalisation</span> rapide pour intervention.</td></tr>\n          <tr><td><span class=\"nc-red nc-bold\">Ischémie aiguë</span> du membre inférieur</td><td>Ischémie par embolie à partir du <span>thrombus</span> de l'AAA : <span class=\"nc-yellow_bg\">prise en charge spécifique immédiate par </span><span><span class=\"nc-yellow_bg\">embolectomie</span></span> ; l'AAA est traité secondairement.</td></tr>\n          <tr><td><span><span class=\"nc-red nc-bold\">Fistule</span></span> aorto-cave</td><td><span><span class=\"nc-red_bg\">Insuffisance cardiaque à débit élevé</span></span> (<span>défaillance</span> hémodynamique sans déglobulisation) → urgence absolue en <span>chirurgie</span> vasculaire.</td></tr>\n          <tr><td><span><span class=\"nc-red nc-bold\">Fistule</span></span> aorto-digestive</td><td><span><span class=\"nc-red_bg\">Hémorragie digestive</span></span> (<span>hématémèse</span> ou <span>rectorragie</span>) avec <span>défaillance</span> hémodynamique → urgence absolue en <span>chirurgie</span> vasculaire.</td></tr>\n        </tbody>\n      </table>\n      <p class=\"obj-renvois\"><em>📎 Items liés : 332 — Etat de <span>choc</span></em></p></div><details><summary>Sources et compléments</summary><p>Relecture du 15 octobre 2026. Couleurs reprises des passages correspondants de ton cours Notion.</p><ul><li><a href=\"https://app.notion.com/p/2ad37f85d941815193ddc58435a90f95?pvs=204\" target=\"_blank\" rel=\"noopener noreferrer\">Ton cours Notion · Anévrisme de l&#x27;aorte abdominale</a></li><li><a href=\"https://www.sfcardio.fr/publication/chapitre-07-item-225-arteriopathie-de-laorte-des-arteres-viscerales-et-des-membres-inferieurs-anevrismes/\" target=\"_blank\" rel=\"noopener noreferrer\">CNEC · Item 225</a></li><li><a href=\"https://esvs.org/guidelines/\" target=\"_blank\" rel=\"noopener noreferrer\">ESVS · Recommandations vasculaires</a></li></ul><p>Les compléments ATLAS sont des synthèses pédagogiques ; les repères historiques et les recommandations plus récentes sont distingués lorsque nécessaire.</p></details>","frequence":4},{"id":"225-16","rang":"A","rubrique":"Définition","titre":"Connaître la définition de l’ischémie intestinale aiguë et chronique","contenu":"<div class=\"notion-course\"><ul><li>L’ischémie mésentérique aiguë est une insuffisance brutale de perfusion intestinale : <span class=\"nc-red nc-bold\">embolie</span> ou thrombose artérielle, ischémie non occlusive de bas débit, ou thrombose veineuse mésentérique. Le diagnostic et la restauration de perfusion sont urgents.</li><li>L’ischémie chronique est le plus souvent athéromateuse et provoque une inadéquation entre apport sanguin et besoins postprandiaux. Une atteinte pluritronculaire est fréquente, mais une atteinte d’un seul axe peut être symptomatique ; « deux axes obligatoires » est trop absolu.</li><li>Tronc cœliaque : estomac, foie, rate et duodénum proximal ; artère mésentérique supérieure : grêle, côlon droit et deux tiers proximaux du transverse ; artère mésentérique inférieure : tiers distal du transverse, côlon gauche, sigmoïde et rectum supérieur.</li><li>Les réseaux collatéraux peuvent compenser une sténose progressive mais ne garantissent pas la viabilité lors d’une occlusion aiguë. Il n’existe pas de délai horaire universel garantissant l’absence de nécrose.</li></ul><figure class=\"obj-figure\">\n        <img src=\"../assets/images/225/vascularisation-digestive.png\" alt=\"Schéma de la vascularisation artérielle de l&#x27;appareil digestif abdominal : tronc cœliaque, artère mésentérique supérieure, artère mésentérique inférieure\" loading=\"lazy\">\n        <figcaption>Vascularisation artérielle de l'appareil digestif abdominal — les 3 axes : tronc cœliaque, artère mésentérique supérieure et inférieure. Source : fiche source EDN item 225.</figcaption>\n      </figure></div><details><summary>Sources et compléments</summary><p>Relecture du 15 octobre 2026. Couleurs reprises des passages correspondants de ton cours Notion.</p><ul><li><a href=\"https://app.notion.com/p/2ad37f85d94181e3bc61dd60c03b6fa6?pvs=204\" target=\"_blank\" rel=\"noopener noreferrer\">Ton cours Notion · Pathologie digestive vasculaire</a></li><li><a href=\"https://www.sfcardio.fr/publication/chapitre-07-item-225-arteriopathie-de-laorte-des-arteres-viscerales-et-des-membres-inferieurs-anevrismes/\" target=\"_blank\" rel=\"noopener noreferrer\">CNEC · Item 225</a></li><li><a href=\"https://esvs.org/guidelines/\" target=\"_blank\" rel=\"noopener noreferrer\">ESVS · Recommandations vasculaires</a></li></ul><p>Les compléments ATLAS sont des synthèses pédagogiques ; les repères historiques et les recommandations plus récentes sont distingués lorsque nécessaire.</p></details>","frequence":0},{"id":"225-17","rang":"A","rubrique":"Diagnostic positif","titre":"Connaître la sémiologie de l’ischémie intestinale aiguë et chronique : signes fonctionnels et signes physiques","contenu":"<div class=\"notion-course\"><h4 style=\"margin:4px 0 6px;font-size:14px;\">Ischémie intestinale chronique</h4>\n      <p><span>Terrain</span> : patient âgé (vers <span>60 ans</span>), à <span class=\"nc-red nc-bold\">terrain cardiovasculaire</span>, avec une <strong><span class=\"nc-pink_bg\">prédominance féminine</span> (<span>70 %</span>)</strong>. La sémiologie repose sur une <span>triade clinique</span> :</p>\n      <ul>\n        <li><strong><span><span class=\"nc-yellow_bg\">Angor mésentérique</span></span></strong> — signe le plus précoce et le plus constant : <span><span class=\"nc-red nc-bold\">crampe post-prandiale</span></span> survenant <span><span class=\"nc-red nc-bold\">15-30 min</span></span><span class=\"nc-red nc-bold\"> après l'ingestion</span>, de siège péri-ombilical ou <span class=\"nc-blue_bg\">épigastrique</span>, d'intensité proportionnelle au volume et à la composition du repas, s'atténuant lentement en <span>1-2 h</span>.</li>\n        <li><strong><span class=\"nc-yellow_bg\">Éviction et fractionnement alimentaire</span></strong> — par crainte des douleurs, pouvant conduire à une dénutrition sévère.</li>\n        <li><strong><span><span class=\"nc-yellow_bg\">Amaigrissement</span></span></strong> — souvent important, conséquence de la dénutrition.</li>\n      </ul>\n      <p>Signes physiques : <span>souffle abdominal</span> souvent présent, autres localisations athéromateuses.</p>\n      <div class=\"callout callout-warn\">\n        <strong><span class=\"nc-red_bg\">Syndrome de </span><span><span class=\"nc-red_bg\">menace</span></span><span class=\"nc-red_bg\"> mésentérique</span>.</strong> Haut risque d'<span>évolution</span> vers l'ischémie intestinale aiguë — à évoquer si la douleur devient <span><span class=\"nc-red nc-bold\">permanente</span></span> ou <span><span class=\"nc-red nc-bold\">nocturne et insomniante</span></span>.\n      </div>\n\n      <h4 style=\"margin:14px 0 6px;font-size:14px;\">Ischémie intestinale aiguë</h4>\n      <table>\n        <thead>\n          <tr><th><span>Stade</span></th><th>Sémiologie</th></tr>\n        </thead>\n        <tbody>\n          <tr><td><strong><span>Stade</span> initial</strong></td><td><span>Douleur abdominale</span> = 1ᵉʳ symptôme, le plus constant : début brutal, intensité <span>croissante et très intense, <span class=\"nc-red nc-bold\">sans répit</span></span>, sans position <span>antalgique</span>. <strong>Dissociation entre l'intensité de la douleur et la pauvreté de l'examen abdominal.</strong> <span class=\"nc-yellow_bg\">Diarrhées</span> fréquentes. Signes négatifs : <span class=\"nc-green_bg\">pas de </span><span><span class=\"nc-green_bg\">fièvre</span></span>, <span class=\"nc-green_bg\">abdomen non distendu</span>, <span class=\"nc-green_bg\">pas de signes péritonéaux</span>.</td></tr>\n          <tr><td><strong><span>Stade</span> tardif</strong></td><td>Tableau d'<span>infarctus intestinal</span> : occlusion (météorisme, <span>vomissements</span> fécaloïdes, abolition des bruits hydro-aériques), puis <span><span class=\"nc-red nc-bold\">signes péritonéaux</span></span> (<span class=\"nc-red_bg\">défense</span>, <span class=\"nc-red_bg\">contracture</span>). <span class=\"nc-red_bg\">Signes généraux</span> : <span><span class=\"nc-blue nc-bold\">fièvre</span></span>, <span><span class=\"nc-blue nc-bold\">état de choc</span></span> progressif, <span>défaillance</span> multiviscérale ; hématochézie.</td></tr>\n        </tbody>\n      </table>\n      <p><strong>Biologie</strong> — <span>hyperleucocytose</span>, <span>acidose métabolique</span>, élévation des <span>lactates</span> et des <span>LDH</span>.</p>\n      <p class=\"obj-renvois\"><em>📎 Items liés : 269 — <span>Douleur abdominale</span> aiguë · 357 — Péritonite aiguë · 355 — Hémorragie digestive</em></p><h4>Points de raisonnement et précautions</h4><ul><li>Douleur disproportionnée par rapport à l’examen : évoquer précocement l’ischémie mésentérique, même avec lactate normal. Angioscanner abdominal urgent avec analyse artérielle et veineuse ; ne pas attendre une péritonite. Réanimation, avis spécialisé et revascularisation/résection selon viabilité ; antibiothérapie et anticoagulation selon mécanisme et contre-indications.</li></ul></div><details><summary>Sources et compléments</summary><p>Relecture du 15 octobre 2026. Couleurs reprises des passages correspondants de ton cours Notion.</p><ul><li><a href=\"https://app.notion.com/p/2ad37f85d94181e3bc61dd60c03b6fa6?pvs=204\" target=\"_blank\" rel=\"noopener noreferrer\">Ton cours Notion · Pathologie digestive vasculaire</a></li><li><a href=\"https://www.sfcardio.fr/publication/chapitre-07-item-225-arteriopathie-de-laorte-des-arteres-viscerales-et-des-membres-inferieurs-anevrismes/\" target=\"_blank\" rel=\"noopener noreferrer\">CNEC · Item 225</a></li><li><a href=\"https://esvs.org/guidelines/\" target=\"_blank\" rel=\"noopener noreferrer\">ESVS · Recommandations vasculaires</a></li></ul><p>Les compléments ATLAS sont des synthèses pédagogiques ; les repères historiques et les recommandations plus récentes sont distingués lorsque nécessaire.</p></details>","frequence":2}],"astuces":[{"type":"piege","titre":"Raisonner avant le chiffre","contenu":"<div class=\"notion-course\"><p>Interpréter un seuil avec le tableau clinique, le référentiel et les unités ; une complication aiguë impose de réévaluer immédiatement la stratégie.</p></div>"},{"type":"piege","titre":"Source et synthèse","contenu":"<div class=\"notion-course\"><p>Les schémas du collège restent accessibles. Les arbres ATLAS et leurs compléments sont explicitement identifiés et reliés aux objectifs concernés.</p></div>"}],"strategie":{"Démarche diagnostique":"<div class=\"notion-course\"><ul><li>Rechercher les signes de gravité puis préciser la probabilité et le mécanisme.</li><li>Choisir les examens capables de modifier la décision et confronter les résultats à la clinique.</li></ul></div>","Prise en charge":"<div class=\"notion-course\"><ul><li>Adapter la prise en charge à l’urgence, au terrain, aux contre-indications et aux préférences.</li><li>Prévoir surveillance, éducation et réévaluation ; utiliser les arbres reliés au cours.</li></ul></div>"},"liensGlobaux":[{"href":"https://app.notion.com/p/2ad37f85d9418121a8bae0f610f004f4?pvs=204","label":"Ton cours Notion ↗"},{"href":"https://www.sfcardio.fr/publication/chapitre-07-item-225-arteriopathie-de-laorte-des-arteres-viscerales-et-des-membres-inferieurs-anevrismes/","label":"CNEC · Item 225 ↗"},{"href":"https://esvs.org/guidelines/","label":"ESVS · Recommandations vasculaires ↗"},{"href":"https://www.has-sante.fr/jcms/c_1361253/en/anevrismes-de-l-aorte-abdominale-en-france-proposer-un-depistage-cible-opportuniste-unique-chez-les-hommes-presentant-des-facteurs-de-risque","label":"HAS · Dépistage ciblé de l’AAA ↗"}],"arbre":{"rootId":"entry","nodes":[{"id":"entry","kind":"decision","label":"Symptômes aigus ou déficit neurologique ?","detail":"<ul><li>Distinguer urgence artérielle et maladie chronique.</li></ul>","branches":[{"label":"Oui","to":"urgent"},{"label":"Non","to":"ips"}]},{"id":"urgent","kind":"urgent","label":"Utiliser le parcours d’ischémie aiguë","detail":"<ul><li>Avis vasculaire immédiat.</li></ul>","branches":[]},{"id":"ips","kind":"decision","label":"IPS et exploration adaptés","detail":"<ul><li>Si incompressible : pression d’orteil ; Doppler selon contexte.</li></ul>","branches":[{"label":"Douleur de repos / plaie / gangrène","to":"menace"},{"label":"Claudication ou asymptomatique","to":"medical"}]},{"id":"menace","kind":"urgent","label":"Ischémie chronique menaçant le membre ?","detail":"<ul><li>Évaluer perfusion, plaie et infection ; avis vasculaire rapide.</li></ul>","branches":[{"label":"Revascularisation à discuter","to":"revasc"}]},{"id":"medical","kind":"decision","label":"Prévention, marche et traitement médical","detail":"<ul><li>Tabac, lipides, PA/diabète ; antithrombotique selon indication.</li></ul>","branches":[{"label":"Handicap persistant malgré traitement","to":"revasc"},{"label":"Contrôle satisfaisant","to":"suivi"}]},{"id":"revasc","kind":"decision","label":"Choix spécialisé selon anatomie et bénéfice","detail":"<ul><li>Endovasculaire, chirurgie ou stratégie de soins adaptée.</li></ul>","branches":[{"label":"Surveillance","to":"suivi"}]},{"id":"suivi","kind":"finish","label":"Suivi du membre et du risque cardiovasculaire","detail":"<ul><li>Pieds, symptômes, traitement et éventuel pontage/stent.</li></ul>","branches":[]}]},"cards":[{"i":"34afcaf7e887","n":225,"o":"225-10","u":"Définition","t":"Connaître la définition et l’histoire naturelle d’un anévrisme de l’aorte abdominale et savoir rechercher d’autres localisations anévrismales","q":"Comment définit-on un anévrisme artériel ?","a":"<div class=\"notion-course\"><p>Un anévrisme artériel est une <strong>dilatation focale et permanente</strong> d'une artère, avec <span class=\"nc-yellow_bg\">perte du parallélisme de ses parois</span>, dont le diamètre est <strong>&gt; 1,5 fois le diamètre d'amont</strong>. La dilatation peut être fusiforme ou sacciforme.</p></div>"},{"i":"3b91b8bde8f2","n":225,"o":"225-10","u":"Définition","t":"Connaître la définition et l’histoire naturelle d’un anévrisme de l’aorte abdominale et savoir rechercher d’autres localisations anévrismales","q":"Lors de la découverte d'un anévrisme de l'aorte abdominale (AAA), quelles autres localisations anévrismales doit-on rechercher systématiquement et avec quelles modalités d'imagerie ?","a":"<div class=\"notion-course\"><ul><li>Rechercher un <span class=\"nc-orange_bg\">anévrisme poplité</span> chez un porteur d’AAA ; ne pas inverser les fréquences d’association AAA–<span class=\"nc-orange_bg\">anévrisme poplité</span>.</li><li><strong><span class=\"nc-orange_bg\">Anévrisme des artères iliaques</span></strong> : À rechercher par <strong><span class=\"nc-blue_bg\">échographie</span>-Doppler ou <span class=\"nc-blue_bg\">angio-TDM</span></strong>.</li><li><strong><span class=\"nc-orange_bg\">Anévrisme de l'aorte thoracique</span></strong> : À rechercher par <strong>angio-TDM thoraco-abdomino-pelvienne</strong>.</li><li>Il convient également de dépister l'<strong>athérosclérose</strong>, notamment coronarienne et des troncs supra-aortiques.</li></ul></div>"},{"i":"47b517bb1431","n":225,"o":"225-10","u":"Définition","t":"Connaître la définition et l’histoire naturelle d’un anévrisme de l’aorte abdominale et savoir rechercher d’autres localisations anévrismales","q":"Quelle est la définition, selon la HAS, d'un anévrisme de l'aorte abdominale (AAA) ?","a":"<div class=\"notion-course\"><p>Un anévrisme de l'aorte abdominale est défini par un <strong>diamètre antéro-postérieur <span class=\"nc-pink nc-bold\">&gt; 30 mm</span></strong>, ou une dilatation <strong>≥ +50%</strong> par rapport au diamètre de l'aorte abdominale sus-jacente normale.</p></div>"},{"i":"d126560e2641","n":225,"o":"225-10","u":"Définition","t":"Connaître la définition et l’histoire naturelle d’un anévrisme de l’aorte abdominale et savoir rechercher d’autres localisations anévrismales","q":"Quelle est l'histoire naturelle de la croissance d'un anévrisme de l'aorte abdominale (AAA) et quels sont les facteurs influençant son risque de rupture ?","a":"<div class=\"notion-course\"><ul><li><strong>Croissance</strong> : En moyenne de <strong>2 à 4 mm/an</strong>. Elle est d'autant <span class=\"nc-red nc-bold\">plus rapide</span> que le diamètre est grand. Un AAA est dit à « croissance rapide » si sa croissance est <span class=\"nc-red nc-bold\">&gt; 1 cm/an</span>.</li><li><strong>Risque de rupture</strong> : Il augmente avec le diamètre (&lt; 0,5% par an si diamètre <span class=\"nc-pink nc-bold\">&lt; 40 mm</span>, puis croissant). Ce risque est <strong><span class=\"nc-red nc-bold\">majoré chez la femme</span></strong><span class=\"nc-red nc-bold\"> à diamètre égal</span> (multiplié par 4).</li></ul></div>"},{"i":"3ad50bace82d","n":225,"o":"225-12","u":"Diagnostic positif","t":"Connaître les signes cliniques des anévrismes de l’aorte","q":"Quels sont les signes cliniques les plus fréquents d'un anévrisme de l'aorte abdominale non compliqué, et comment est-il généralement découvert ?","a":"<div class=\"notion-course\"><p>L'anévrisme de l'aorte abdominale est le plus souvent <strong>asymptomatique</strong> et découvert de façon fortuite. Cliniquement, il peut se présenter comme une <strong>masse abdominale battante et expansive</strong> de la région para-ombilicale, <span class=\"nc-blue_bg\">avec ou sans souffle</span>. Elle est palpable surtout chez les sujets maigres ou si l'anévrisme est volumineux. La découverte se fait également par imagerie (échographie, TDM, IRM).</p></div>"},{"i":"3b77051bba8d","n":225,"o":"225-12","u":"Diagnostic positif","t":"Connaître les signes cliniques des anévrismes de l’aorte","q":"Quels sont les signes cliniques et biologiques d'un anévrisme de l'aorte inflammatoire ?","a":"<div class=\"notion-course\"><p>Un anévrisme de l'aorte inflammatoire, dû à une gangue inflammatoire péri-anévrismale, se manifeste par une <strong>fièvre</strong>, une <strong>altération de l'état général (AEG)</strong> et un <strong>syndrome inflammatoire biologique</strong> (augmentation de la vitesse de sédimentation (VS) et de la C-réactive protéine (CRP)).</p></div>"},{"i":"4d5f5db3a9a2","n":225,"o":"225-12","u":"Diagnostic positif","t":"Connaître les signes cliniques des anévrismes de l’aorte","q":"Quels sont les signes cliniques d'une complication embolique à partir d'un anévrisme de l'aorte abdominale ?","a":"<div class=\"notion-course\"><p>Une complication embolique à partir du thrombus intra-anévrismal peut se manifester par une <strong><span class=\"nc-red nc-bold\">occlusion artérielle aiguë du membre inférieur</span></strong> ou des <strong><span class=\"nc-red nc-bold\">embolies de cristaux de cholestérol</span></strong> (par exemple, un orteil bleu).</p></div>"},{"i":"4f74b63beaa1","n":225,"o":"225-12","u":"Diagnostic positif","t":"Connaître les signes cliniques des anévrismes de l’aorte","q":"Quels sont les syndromes cliniques liés à la compression des organes adjacents par un anévrisme de l'aorte abdominale ?","a":"<div class=\"notion-course\"><ul><li>Compression du <strong>duodénum</strong> : vomissements post-prandiaux.</li><li>Compression des <strong>nerfs</strong> : radiculalgies.</li><li>Compression de la <strong>veine cave inférieure (VCI)</strong> : œdèmes des membres inférieurs.</li><li>Compression des <strong>os</strong> : érosions vertébrales.</li><li>Compression des <strong>voies urinaires</strong> : coliques néphrétiques.</li></ul></div>"},{"i":"972ae32c0cce","n":225,"o":"225-12","u":"Diagnostic positif","t":"Connaître les signes cliniques des anévrismes de l’aorte","q":"Quels sont les signes cliniques évocateurs d'une fissuration ou d'une rupture d'anévrisme de l'aorte abdominale ?","a":"<div class=\"notion-course\"><p>Une <span class=\"nc-red nc-bold\">fissuration</span> ou une <span class=\"nc-red nc-bold\">rupture</span> d'anévrisme de l'aorte abdominale se traduit cliniquement par une <strong><span class=\"nc-blue_bg\">douleur abdominale ou lombaire</span></strong>, pouvant être associée à un <strong>tableau de choc hémorragique</strong>. On distingue la <span class=\"nc-red nc-bold\">rupture</span> rétropéritonéale (syndrome fissuraire) et la <span class=\"nc-red nc-bold\">rupture</span> intrapéritonéale (souvent foudroyante).</p></div>"},{"i":"9a64b9d4aebd","n":225,"o":"225-12","u":"Diagnostic positif","t":"Connaître les signes cliniques des anévrismes de l’aorte","q":"Quelles sont les manifestations cliniques des fistules aortiques ?","a":"<div class=\"notion-course\"><ul><li>Une <strong><span class=\"nc-red nc-bold\">fistule</span> aorto-cave</strong> provoque une <strong><span class=\"nc-red_bg\">insuffisance cardiaque à débit élevé</span></strong>.</li><li>Une <strong><span class=\"nc-red nc-bold\">fistule</span> aorto-digestive</strong> entraîne une <strong><span class=\"nc-red_bg\">hémorragie digestive</span></strong> (hématémèse, rectorragie).</li></ul></div>"},{"i":"ed3d9ae54033","n":225,"o":"225-12","u":"Diagnostic positif","t":"Connaître les signes cliniques des anévrismes de l’aorte","q":"Comment le signe de Bakey peut-il orienter sur la localisation d'un anévrisme de l'aorte abdominale ?","a":"<div class=\"notion-course\"><p>Le <strong>signe de Bakey</strong> correspond à la possibilité de glisser la main entre le pôle supérieur de l'anévrisme et les côtes du patient. Sa présence est en faveur d'un <strong>anévrisme sous-rénal</strong>.</p></div>"},{"i":"1a0d07511a89","n":225,"o":"225-13","u":"Examens complémentaires","t":"Savoir comment faire le diagnostic des anévrysmes de l’aorte abdominale","q":"Quelle est la place de l'artériographie dans le diagnostic des anévrismes de l'aorte abdominale (AAA) ?","a":"<div class=\"notion-course\"><p>L'artériographie n'a <strong>plus d'indication diagnostique</strong> pour les anévrismes de l'aorte abdominale (AAA) car elle ne révèle que la lumière artérielle et ne permet pas une mesure fiable du diamètre en raison du thrombus mural fréquent.</p></div>"},{"i":"3d7951002dcf","n":225,"o":"225-13","u":"Examens complémentaires","t":"Savoir comment faire le diagnostic des anévrysmes de l’aorte abdominale","q":"Quel est l'examen de référence pour l'évaluation pré-thérapeutique d'un anévrisme de l'aorte abdominale (AAA) ?","a":"<div class=\"notion-course\"><p>L'examen de référence pour l'évaluation pré-thérapeutique d'un anévrisme de l'aorte abdominale (AAA) est la <strong>TDM thoraco-abdomino-pelvienne injectée</strong>. Elle précise les diamètres et l'extension par rapport aux artères rénales et iliaques.</p></div>"},{"i":"4afd80fbbc8b","n":225,"o":"225-13","u":"Examens complémentaires","t":"Savoir comment faire le diagnostic des anévrysmes de l’aorte abdominale","q":"Quels éléments ne modifient pas la prise en charge d'un anévrisme de l'aorte abdominale (AAA), le diamètre étant le critère principal ?","a":"<div class=\"notion-course\"><p>Le diamètre maximal guide le risque, mais symptômes, <span class=\"nc-brown_bg\">croissance</span>, morphologie, collet, thrombus et rapports aux branches comptent également, notamment pour planifier une réparation.</p></div>"},{"i":"cac2503e4be6","n":225,"o":"225-13","u":"Examens complémentaires","t":"Savoir comment faire le diagnostic des anévrysmes de l’aorte abdominale","q":"Quelle recherche systématique doit être menée lors de la découverte d'un anévrisme de l'aorte abdominale (AAA) ?","a":"<div class=\"notion-course\"><p>Rechercher un <span class=\"nc-orange_bg\">anévrisme poplité</span> chez un porteur d’AAA ; ne pas inverser les fréquences d’association AAA–<span class=\"nc-orange_bg\">anévrisme poplité</span>.</p></div>"},{"i":"e4ce99563360","n":225,"o":"225-13","u":"Examens complémentaires","t":"Savoir comment faire le diagnostic des anévrysmes de l’aorte abdominale","q":"Dans quel cas une TDM thoraco-abdomino-pelvienne injectée est-elle indiquée en urgence pour un anévrisme de l'aorte abdominale (AAA) ?","a":"<div class=\"notion-course\"><p>Une TDM thoraco-abdomino-pelvienne injectée est indiquée <span class=\"nc-red nc-bold\">en urgence en cas d'</span><strong><span class=\"nc-red nc-bold\">AAA douloureux</span></strong><span class=\"nc-red nc-bold\"> ou de </span><strong><span class=\"nc-red nc-bold\">suspicion de rupture</span></strong>.</p></div>"},{"i":"f3cbf68f204c","n":225,"o":"225-13","u":"Examens complémentaires","t":"Savoir comment faire le diagnostic des anévrysmes de l’aorte abdominale","q":"Quel est l'examen de dépistage et de suivi de première intention pour un anévrisme de l'aorte abdominale (AAA) asymptomatique ?","a":"<div class=\"notion-course\"><p>L'<span class=\"nc-yellow_bg\">examen de</span> <span class=\"nc-yellow_bg nc-bold\">dépistage</span> <span class=\"nc-yellow_bg\">et de</span> suivi de première intention pour un anévrisme de l'aorte abdominale (AAA) asymptomatique est l'<strong>échographie abdominale</strong>. Elle permet d'obtenir le diamètre maximal <span class=\"nc-yellow_bg\">et de</span> surveiller la croissance de l'anévrisme.</p></div>"},{"i":"1518d7b4458a","n":225,"o":"225-15","u":"Identifier une urgence","t":"Savoir reconnaître et prendre en charge une situation d’urgence chez les patient porteur d’un anévrisme de l’aorte abdominale","q":"Quelle est la prise en charge d'une ischémie aiguë du membre inférieur compliquant un AAA ?","a":"<div class=\"notion-course\"><p>L'<span class=\"nc-red nc-bold\">ischémie aiguë</span> du membre inférieur, souvent due à une embolie à partir du thrombus de l'AAA, nécessite une <strong><span class=\"nc-yellow_bg\">prise en charge spécifique immédiate par embolectomie</span></strong>. L'AAA sera traité secondairement.</p></div>"},{"i":"54b37c208b63","n":225,"o":"225-15","u":"Identifier une urgence","t":"Savoir reconnaître et prendre en charge une situation d’urgence chez les patient porteur d’un anévrisme de l’aorte abdominale","q":"Comment identifier et prendre en charge d'une fistule aorto-digestive liée à un AAA ?","a":"<div class=\"notion-course\"><p>Une <span class=\"nc-red nc-bold\">fistule</span> aorto-digestive se manifeste par une <strong><span class=\"nc-red_bg\">hémorragie digestive</span></strong> (<strong>hématémèse</strong> ou <strong>rectorragie</strong>) associée à une <strong>défaillance hémodynamique</strong>. C'est une urgence absolue en chirurgie vasculaire et nécessite une <strong>intervention immédiate</strong>.</p></div>"},{"i":"61b20f37f977","n":225,"o":"225-15","u":"Identifier une urgence","t":"Savoir reconnaître et prendre en charge une situation d’urgence chez les patient porteur d’un anévrisme de l’aorte abdominale","q":"Quand est-ce qu'une TDM peut être réalisée chez un patient suspect d'AAA rompu ?","a":"<div class=\"notion-course\"><p>Une TDM peut être réalisée uniquement si l'<strong>état hémodynamique le permet</strong>. Elle ne doit en aucun cas retarder une intervention chirurgicale chez un patient en choc hémorragique.</p></div>"},{"i":"81295e1007bf","n":225,"o":"225-15","u":"Identifier une urgence","t":"Savoir reconnaître et prendre en charge une situation d’urgence chez les patient porteur d’un anévrisme de l’aorte abdominale","q":"Comment doit être pris en charge un patient présentant un AAA douloureux (non rompu) en urgence ?","a":"<div class=\"notion-course\"><p>Un AAA douloureux nécessite une <strong><span class=\"nc-blue_bg\">TDM en urgence</span></strong>, une prise en charge de l'<strong>état général, cardiovasculaire, rénal et respiratoire</strong>, et une <strong>hospitalisation rapide pour intervention</strong>.</p></div>"},{"i":"cc360c871990","n":225,"o":"225-15","u":"Identifier une urgence","t":"Savoir reconnaître et prendre en charge une situation d’urgence chez les patient porteur d’un anévrisme de l’aorte abdominale","q":"Quelle est la conduite à tenir en urgence face à un patient présentant un anévrisme de l'aorte abdominale (AAA) rompu ?","a":"<div class=\"notion-course\"><p>Un AAA rompu est une <strong>urgence extrême</strong>. La conduite à tenir est une orientation immédiate vers un <strong>centre spécialisé de chirurgie vasculaire</strong>. Si le patient est en <strong>choc hémorragique</strong>, aucune imagerie ne doit retarder l'intervention. Si les mesures de réanimation ne stabilisent pas le patient, un <strong>passage direct au bloc opératoire</strong> est indiqué.</p></div>"},{"i":"d4d101ab20e9","n":225,"o":"225-15","u":"Identifier une urgence","t":"Savoir reconnaître et prendre en charge une situation d’urgence chez les patient porteur d’un anévrisme de l’aorte abdominale","q":"Quelle est la conduite à tenir face à une fistule aorto-cave suite à un AAA ?","a":"<div class=\"notion-course\"><p>Une <span class=\"nc-red nc-bold\">fistule</span> aorto-cave se manifeste par une <strong><span class=\"nc-red_bg\">insuffisance cardiaque à débit élevé</span></strong> (défaillance hémodynamique sans déglobulisation) et constitue une urgence absolue en chirurgie vasculaire, nécessitant une <strong>intervention immédiate</strong>.</p></div>"},{"i":"3e27692bd3f7","n":225,"o":"225-16","u":"Définition","t":"Connaître la définition de l’ischémie intestinale aiguë et chronique","q":"Quelle est la définition de l'ischémie intestinale aiguë (ou infarctus mésentérique) ?","a":"<div class=\"notion-course\"><ul><li>L’ischémie mésentérique aiguë est une insuffisance brutale de perfusion intestinale : <span class=\"nc-red nc-bold\">embolie</span> ou thrombose artérielle, ischémie non occlusive de bas débit, ou thrombose veineuse mésentérique. Le diagnostic et la restauration de perfusion sont urgents.</li></ul></div>"},{"i":"97a5ef226388","n":225,"o":"225-16","u":"Définition","t":"Connaître la définition de l’ischémie intestinale aiguë et chronique","q":"Quelle est la définition de l'ischémie intestinale chronique ?","a":"<div class=\"notion-course\"><ul><li>L’ischémie chronique est le plus souvent athéromateuse et provoque une inadéquation entre apport sanguin et besoins postprandiaux. Une atteinte pluritronculaire est fréquente, mais une atteinte d’un seul axe peut être symptomatique ; « deux axes obligatoires » est trop absolu.</li></ul></div>"},{"i":"c28ccbb60330","n":225,"o":"225-16","u":"Définition","t":"Connaître la définition de l’ischémie intestinale aiguë et chronique","q":"Pourquoi l'ischémie du grêle est-elle particulièrement grave ?","a":"<div class=\"notion-course\"><ul><li>L’ischémie mésentérique aiguë est une insuffisance brutale de perfusion intestinale : <span class=\"nc-red nc-bold\">embolie</span> ou thrombose artérielle, ischémie non occlusive de bas débit, ou thrombose veineuse mésentérique. Le diagnostic et la restauration de perfusion sont urgents.</li><li>Les réseaux collatéraux peuvent compenser une sténose progressive mais ne garantissent pas la viabilité lors d’une occlusion aiguë. Il n’existe pas de délai horaire universel garantissant l’absence de nécrose.</li></ul></div>"},{"i":"d5dd03197db9","n":225,"o":"225-16","u":"Définition","t":"Connaître la définition de l’ischémie intestinale aiguë et chronique","q":"Quels sont les principaux axes artériels assurant la vascularisation du tube digestif ?","a":"<div class=\"notion-course\"><ul><li>Tronc cœliaque : estomac, foie, rate et duodénum proximal ; artère mésentérique supérieure : grêle, côlon droit et deux tiers proximaux du transverse ; artère mésentérique inférieure : tiers distal du transverse, côlon gauche, sigmoïde et rectum supérieur.</li></ul></div>"},{"i":"33e9566b2dc1","n":225,"o":"225-17","u":"Diagnostic positif","t":"Connaître la sémiologie de l’ischémie intestinale aiguë et chronique : signes fonctionnels et signes physiques","q":"Quels signes physiques peuvent être retrouvés à l'examen clinique chez un patient présentant une ischémie intestinale chronique ?","a":"<div class=\"notion-course\"><p>À l'examen clinique d'une ischémie intestinale chronique, on peut retrouver :</p><ul><li>Un <strong>souffle abdominal</strong>, souvent présent.</li><li>D'<strong>autres localisations athéromateuses</strong>.</li></ul></div>"},{"i":"3f795c950a2d","n":225,"o":"225-17","u":"Diagnostic positif","t":"Connaître la sémiologie de l’ischémie intestinale aiguë et chronique : signes fonctionnels et signes physiques","q":"Quels sont les signes cliniques du stade initial de l'ischémie intestinale aiguë ?","a":"<div class=\"notion-course\"><p>Au stade initial de l'ischémie intestinale aiguë, les signes cliniques sont :</p><ul><li>Une <strong>douleur abdominale</strong> de début <strong>brutal</strong>, d'intensité <strong>croissante et très intense</strong>, <span class=\"nc-red nc-bold\">sans répit</span> et sans position antalgique.</li><li>Une <strong>discordance</strong> entre l'intensité de la douleur et la pauvreté de l'examen abdominal.</li><li>Des <strong><span class=\"nc-yellow_bg\">diarrhées</span> fréquentes</strong>.</li><li>L'absence de <span class=\"nc-blue nc-bold\">fièvre</span>, d'abdomen distendu et de <span class=\"nc-red nc-bold\">signes péritonéaux</span> (<strong>signes négatifs</strong>).</li></ul></div>"},{"i":"8340f6b13ce0","n":225,"o":"225-17","u":"Diagnostic positif","t":"Connaître la sémiologie de l’ischémie intestinale aiguë et chronique : signes fonctionnels et signes physiques","q":"Quelle est la triade clinique caractéristique de l'ischémie intestinale chronique ?","a":"<div class=\"notion-course\"><p>La triade clinique de l'ischémie intestinale chronique est :</p><ul><li>L'<strong><span class=\"nc-yellow_bg\">angor mésentérique</span></strong> : <span class=\"nc-red nc-bold\">crampe post-prandiale</span> survenant <strong><span class=\"nc-red nc-bold\">15-30 min après l'ingestion</span></strong>, péri-ombilicale ou <span class=\"nc-blue_bg\">épigastrique</span>, proportionnelle au repas et s'atténuant en 1-2 h.</li><li>L'<strong>éviction et le fractionnement alimentaire</strong> par crainte des douleurs.</li><li>L'<strong><span class=\"nc-yellow_bg\">amaigrissement</span></strong>, souvent important et lié à la dénutrition.</li></ul></div>"},{"i":"dbe550ca8e2a","n":225,"o":"225-17","u":"Diagnostic positif","t":"Connaître la sémiologie de l’ischémie intestinale aiguë et chronique : signes fonctionnels et signes physiques","q":"Quels sont les signes cliniques et biologiques du stade tardif de l'ischémie intestinale aiguë ?","a":"<div class=\"notion-course\"><p>Au stade tardif de l'ischémie intestinale aiguë, traduisant un infarctus intestinal, on observe :</p><ul><li>Des signes d'<strong>occlusion</strong> (météorisme, vomissements fécaloïdes, abolition des bruits hydro-aériques).</li><li>Des <strong><span class=\"nc-red nc-bold\">signes péritonéaux</span></strong> (<span class=\"nc-red_bg\">défense</span>, <span class=\"nc-red_bg\">contracture</span>).</li><li>Des <span class=\"nc-red_bg\">signes généraux</span> : <strong><span class=\"nc-blue nc-bold\">fièvre</span></strong>, <span class=\"nc-blue nc-bold\">état de choc</span> progressif, défaillance multiviscérale.</li><li>Une <strong>hématochézie</strong>.</li><li>Biologiquement : <strong>hyperleucocytose</strong>, <strong>acidose métabolique</strong>, élévation des <strong>lactates</strong> et des <strong>LDH</strong>.</li></ul></div>"},{"i":"028929c99490","n":225,"o":"225-3","u":"Diagnostic positif","t":"Connaître les manifestations cliniques et la classification de l’AOMI et savoir évoquer les diagnostics différentiels","q":"Quels sont les signes cliniques caractéristiques de l'ischémie d'effort (claudication intermittente) dans l'AOMI ?","a":"<div class=\"notion-course\"><p>Les signes cliniques de l'ischémie d'effort sont :</p><ul><li><strong>Type</strong> : <span class=\"nc-yellow_bg\">crampe</span> musculaire.</li><li><strong>Topographie</strong> : typiquement au <span class=\"nc-yellow_bg\">mollet</span>, mais peut être au pied, à la <span class=\"nc-yellow_bg\">cuisse</span> ou fessière (par atteinte <span class=\"nc-pink nc-bold\">aorto-iliaque</span>).</li><li><strong>Distance de gêne</strong> : distance à laquelle la douleur apparaît.</li><li><strong>Distance de marche</strong> : distance parcourue avant que la douleur n'oblige à l'arrêt (sévère si <span class=\"nc-red nc-bold\">&lt; </span><strong><span class=\"nc-red nc-bold\">100 m</span></strong> sur terrain plat).</li><li><strong>Disparition</strong> : habituellement en <span class=\"nc-green_bg nc-bold\">&lt; </span><strong><span class=\"nc-green_bg nc-bold\">5 minutes</span></strong> à l'arrêt.</li><li><strong>Formes atypiques</strong> : distances variables, <span class=\"nc-brown_bg\">paresthésie</span> d'effort, ralentissement du pas sans arrêt obligé.</li></ul></div>"},{"i":"0a50ea375430","n":225,"o":"225-3","u":"Diagnostic positif","t":"Connaître les manifestations cliniques et la classification de l’AOMI et savoir évoquer les diagnostics différentiels","q":"Quelles sont les manifestations cliniques des stades 3 et 4 de l'AOMI (ischémie permanente ou critique) ?","a":"<div class=\"notion-course\"><p>Les manifestations cliniques de l'<span class=\"nc-brown_bg\">ischémie permanente</span>/critique (stade 3 et 4) sont :</p><ul><li><strong>Douleur de repos (stade 3)</strong> : à type de <strong><span class=\"nc-yellow_bg\">brûlure</span></strong>, localisée aux <span class=\"nc-blue nc-bold\">orteils</span> ou à l'<span class=\"nc-yellow_bg\">avant-pied</span>, survenant après quelques minutes/heures de décubitus, et calmée par la <span class=\"nc-green_bg\">position </span><strong><span class=\"nc-green_bg\">déclive</span></strong> (jambes pendantes). Elle dure <span class=\"nc-pink nc-bold\">&gt; </span><strong><span class=\"nc-pink nc-bold\">15 jours</span></strong> et résiste aux antalgiques usuels.</li><li><strong>Troubles trophiques (stade 4)</strong> : <span class=\"nc-blue_bg\">peau mince</span> et <span class=\"nc-blue_bg\">fragile</span>, <span class=\"nc-red_bg\">dépilation</span>, <strong><span class=\"nc-red_bg\">ulcère artériel</span></strong>, <strong><span class=\"nc-red_bg\">gangrène</span></strong> (<span class=\"nc-blue nc-bold\">orteils</span>, <span class=\"nc-blue nc-bold\">talon</span>), et portes d'entrée infectieuses.</li></ul><p>L'IPS est ≤ 0,9, et la pression à la cheville ≤ 50 mmHg.</p></div>"},{"i":"63be3e4554d4","n":225,"o":"225-3","u":"Diagnostic positif","t":"Connaître les manifestations cliniques et la classification de l’AOMI et savoir évoquer les diagnostics différentiels","q":"Quelles sont les caractéristiques du Syndrome de Leriche ?","a":"<div class=\"notion-course\"><p>Le Syndrome de Leriche est une atteinte <strong><span class=\"nc-pink nc-bold\">aorto-iliaque</span></strong> (aorte sous-rénale + artères iliaques primitives) qui associe :</p><ul><li><strong>claudication fessière bilatérale</strong> et/ou fatigabilité à la marche.</li><li><strong>dysfonction érectile</strong> chez l'homme.</li><li><strong>abolition des deux pouls fémoraux</strong>.</li><li><strong>atrophie musculaire</strong> des membres inférieurs.</li></ul></div>"},{"i":"673fef091762","n":225,"o":"225-3","u":"Diagnostic positif","t":"Connaître les manifestations cliniques et la classification de l’AOMI et savoir évoquer les diagnostics différentiels","q":"Comment l'abolition des pouls périphériques ou un souffle vasculaire peuvent-ils orienter vers un diagnostic d'AOMI ?","a":"<div class=\"notion-course\"><ul><li>Une sténose artérielle peut être suspectée devant un <strong><span class=\"nc-blue_bg\">souffle vasculaire</span></strong>.</li><li>Une obstruction artérielle se manifeste par une <strong><span class=\"nc-blue_bg\">abolition de pouls</span></strong><span class=\"nc-blue_bg\"> en aval</span> sans <span class=\"nc-blue_bg\">souffle</span>.</li><li>L'AOMI asymptomatique (stade 1) peut être évoquée devant un <span class=\"nc-blue_bg\">souffle vasculaire</span> ou une <span class=\"nc-blue_bg\">abolition de pouls périphériques</span> chez un patient à <strong>facteurs de risque cardiovasculaire (FRCV)</strong>, ou une dysfonction érectile chez un patient à FRCV. La confirmation se fait par un IPS ≤ <strong>0,90</strong>.</li></ul></div>"},{"i":"eb28b18cd8ab","n":225,"o":"225-3","u":"Diagnostic positif","t":"Connaître les manifestations cliniques et la classification de l’AOMI et savoir évoquer les diagnostics différentiels","q":"Comment est classifiée cliniquement l'artériopathie oblitérante des membres inférieurs (AOMI) selon les stades clinico-hémodynamiques ?","a":"<div class=\"notion-course\"><p>L'AOMI est classifiée en 3 stades clinico-hémodynamiques :</p><ul><li><strong>Asymptomatique</strong> : Aucun symptôme, IPS ≤ 0,9, PA cheville &gt; 50 mmHg.</li><li><strong>Ischémie d'effort (claudication intermittente)</strong> : Douleur type <span class=\"nc-yellow_bg\">crampe</span> à l'effort, IPS ≤ 0,9, PA cheville <span class=\"nc-pink nc-bold\">&gt; 50 mmHg</span>.</li><li><strong><span class=\"nc-brown_bg\">Ischémie permanente</span> (critique)</strong> : Douleurs de décubitus au repos ± troubles trophiques, IPS ≤ 0,9, PA cheville ≤ 50 mmHg.</li></ul></div>"},{"i":"ef4aa8b1618e","n":225,"o":"225-3","u":"Diagnostic positif","t":"Connaître les manifestations cliniques et la classification de l’AOMI et savoir évoquer les diagnostics différentiels","q":"Quels sont les diagnostics différentiels de la claudication intermittente et comment les distinguer ?","a":"<div class=\"notion-course\"><ul><li>La claudication artérielle est reproductible pour un niveau d’effort donné, avec distance variable selon pente, vitesse et conditions ; elle cède généralement rapidement à l’arrêt.</li><li><strong>Claudication veineuse</strong> : Distance d'apparition variable, gonflement douloureux progressif n'obligeant pas à l'arrêt, récupération lente. Contexte de troubles veineux (ex: syndrome post-thrombotique).</li><li><strong>Claudication articulaire</strong> : Douleur dès les premiers pas, topographie articulaire, d'emblée maximale, récupération lente. Contexte d'arthrose ou rhumatisme inflammatoire.</li><li><strong>Claudication neurologique</strong> : Distance d'apparition variable, douleur soulagée par l'antéflexion, topographie radiculaire. Contexte de canal lombaire étroit ou arthrose lombaire.</li></ul></div>"},{"i":"6a993ee50230","n":225,"o":"225-4","u":"Examens complémentaires","t":"Savoir prescrire les examens complémentaires de première intention","q":"Quels sont les autres examens de première intention pertinents dans le bilan de l'AOMI, en dehors de l'IPS ?","a":"<div class=\"notion-course\"><ul><li>Le <strong>test de marche</strong> pour sensibiliser le diagnostic et confirmer l'origine artérielle de la claudication.</li><li>L'<strong>Écho-Doppler artériel</strong> pour localiser les lésions artérielles et leur retentissement hémodynamique.</li><li>La mesure de la <strong>TcPO2</strong> (Oxygène transcutané) pour évaluer l'<span class=\"nc-red nc-bold\">ischémie critique</span>.</li><li>Le <strong>bilan biologique des facteurs de risque cardiovasculaire (FRCV)</strong> (recherche de dyslipidémie, <span class=\"nc-red_bg\">diabète</span>, insuffisance rénale chronique).</li></ul></div>"},{"i":"9b3c511651e3","n":225,"o":"225-4","u":"Examens complémentaires","t":"Savoir prescrire les examens complémentaires de première intention","q":"Quel est l'examen clé de première intention pour confirmer le diagnostic de l'artériopathie oblitérante des membres inférieurs (AOMI) ?","a":"<div class=\"notion-course\"><p>L'examen clé de première intention pour confirmer le diagnostic de l'AOMI est la mesure de l'<strong>Index de Pression Systolique (IPS)</strong>.</p></div>"},{"i":"d9bf5f4a3cec","n":225,"o":"225-4","u":"Examens complémentaires","t":"Savoir prescrire les examens complémentaires de première intention","q":"Quand les examens de deuxième intention sont-ils envisagés dans le bilan de l'AOMI et quels sont-ils ?","a":"<div class=\"notion-course\"><p>Les examens de deuxième intention sont envisagés <strong>uniquement si une revascularisation est envisagée</strong>. Ils comprennent :</p><ul><li>L'<strong>Angio-TDM</strong>.</li><li>L'<strong>Angio-IRM</strong>.</li><li>L'<strong>Artériographie</strong>.</li></ul></div>"},{"i":"f547dad32720","n":225,"o":"225-4","u":"Examens complémentaires","t":"Savoir prescrire les examens complémentaires de première intention","q":"Comment interprète-t-on les valeurs de l'Index de Pression Systolique (IPS) dans le diagnostic de l'AOMI ?","a":"<div class=\"notion-course\"><ul><li>Une valeur d'IPS entre <strong>1 et 1,40</strong> est normale.</li><li>Un IPS <strong>&lt; 0,90</strong> est évocateur d'AOMI et constitue un marqueur de risque cardiovasculaire élevé.</li><li>Un IPS <strong>&lt; 0,70</strong> indique une <span class=\"nc-red_bg\">AOMI sévère</span>.</li><li>Un <span class=\"nc-yellow_bg\">IPS </span><strong><span class=\"nc-yellow_bg\">&gt; 1,40</span></strong> suggère une <strong><span class=\"nc-yellow_bg\">médiacalcose</span></strong> (rigidité artérielle) rendant la pression de cheville ininterprétable.</li></ul></div>"},{"i":"14f6b02cf2a1","n":225,"o":"225-5","u":"Prise en charge","t":"Connaître le traitement médical : traitement médicamenteux et principes du traitement chirurgical","q":"Quelles sont les indications de la revascularisation dans l'artériopathie oblitérante des membres inférieurs (AOMI) ?","a":"<div class=\"notion-course\"><p>Les indications de la revascularisation sont :</p><ul><li>Une <strong><span class=\"nc-brown_bg\">ischémie permanente</span></strong>.</li><li>Une <strong>claudication intermittente sévère</strong> après traitement médical bien mené de <strong>plus de 3-6 mois</strong>.</li><li>Un <strong>périmètre de marche très faible (<span class=\"nc-red nc-bold\">&lt; 100 m</span>)</strong> avec un handicap important.</li><li>Des <strong><span class=\"nc-brown_bg\">atteintes aorto-iliaques sévères et extensives</span></strong>.</li></ul></div>"},{"i":"44448f17710a","n":225,"o":"225-5","u":"Prise en charge","t":"Connaître le traitement médical : traitement médicamenteux et principes du traitement chirurgical","q":"Quelles sont les principales techniques de revascularisation dans l'artériopathie oblitérante des membres inférieurs (AOMI) et leurs principes ?","a":"<div class=\"notion-course\"><p>Les principales techniques sont :</p><ul><li>La technique <strong>endovasculaire</strong> : <span class=\"nc-pink nc-bold\">angioplastie intraluminale par ballonnet</span> ± pose de <span class=\"nc-pink nc-bold\">stent</span>, avec de meilleurs résultats sur les <strong>lésions <span class=\"nc-green nc-bold\">courtes</span> et <span class=\"nc-green nc-bold\">proximales</span></strong>. Nécessite une <strong><span class=\"nc-pink nc-bold\">bithérapie antiplaquettaire</span> de 1 à 6 mois</strong>.</li><li>La <strong>chirurgie</strong> : principalement le <strong><span class=\"nc-pink nc-bold\">pontage</span></strong> (aorto-bifémoral, fémoro-poplité, fémoro-jambier) ; une <strong>endartériectomie</strong> peut y être associée.</li></ul></div>"},{"i":"c0f71b79e263","n":225,"o":"225-5","u":"Prise en charge","t":"Connaître le traitement médical : traitement médicamenteux et principes du traitement chirurgical","q":"Quels sont les objectifs du traitement de l'artériopathie oblitérante des membres inférieurs (AOMI) ?","a":"<div class=\"notion-course\"><p>Le traitement de l'AOMI a deux objectifs principaux :</p><ul><li>Une visée générale : améliorer le <strong>pronostic cardiovasculaire et vital</strong>.</li><li>Une visée locale : <strong>résoudre les symptômes</strong> et améliorer le <strong>pronostic du membre</strong>.</li></ul></div>"},{"i":"d3c88e0ebc69","n":225,"o":"225-5","u":"Prise en charge","t":"Connaître le traitement médical : traitement médicamenteux et principes du traitement chirurgical","q":"Quelles sont les mesures générales non médicamenteuses recommandées pour la prise en charge de l'artériopathie oblitérante des membres inférieurs (AOMI) ?","a":"<div class=\"notion-course\"><p>Les mesures générales incluent :</p><ul><li>La prise en charge des <strong>facteurs de risque cardiovasculaires (FRCV)</strong>, notamment l'<strong>arrêt du <span class=\"nc-red_bg\">tabac</span></strong> et le contrôle du <span class=\"nc-red_bg\">diabète</span>.</li><li>La <strong>marche / réadaptation supervisée</strong> : <strong><span class=\"nc-pink nc-bold\">30-45 minutes</span></strong>, <strong><span class=\"nc-pink nc-bold\">≥ 3 fois/semaine</span></strong>, pour favoriser la circulation collatérale.</li><li>Les <strong>soins de plaies</strong>, sous la supervision d'une équipe multidisciplinaire spécialisée.</li></ul></div>"},{"i":"da60e784baec","n":225,"o":"225-5","u":"Prise en charge","t":"Connaître le traitement médical : traitement médicamenteux et principes du traitement chirurgical","q":"Quand l'amputation est-elle envisagée dans la prise en charge de l'artériopathie oblitérante des membres inférieurs (AOMI) et quels sont ses principes ?","a":"<div class=\"notion-course\"><p>L'amputation est le <strong>geste ultime</strong>, envisagé à défaut de toute possibilité de revascularisation. Elle est réalisée en <strong>zone saine et bien oxygénée</strong> (intérêt de la TcPO2), en sauvegardant autant que possible l'appui et l'articulation du genou pour faciliter l'appareillage par prothèse.</p></div>"},{"i":"f2bea3201b77","n":225,"o":"225-5","u":"Prise en charge","t":"Connaître le traitement médical : traitement médicamenteux et principes du traitement chirurgical","q":"Quels sont les traitements médicamenteux essentiels dans la prise en charge de l'artériopathie oblitérante des membres inférieurs (AOMI) et leurs objectifs ?","a":"<div class=\"notion-course\"><p>Les traitements médicamenteux essentiels sont :</p><ul><li>Les <strong>antiplaquettaires</strong> (aspirine) : à dose antiagrégante, indication discutée si AOMI asymptomatique isolée.</li><li>Les <strong><span class=\"nc-pink_bg\">statines</span></strong> : objectif <strong>LDL <span class=\"nc-pink\">&lt; 0,55 g/L</span></strong> et réduction ≥ 50 % de la valeur initiale.</li><li>Les <strong><span class=\"nc-pink_bg\">IEC</span></strong> : objectif <strong>PA <span class=\"nc-pink\">&lt; 140/90 mmHg</span></strong>, intérêt pronostique même sans HTA.</li><li>Les <strong>bêta-bloquants</strong> : à utiliser avec prudence si <span class=\"nc-red nc-bold\">ischémie critique</span> non revascularisable, possibles si indication formelle (cardiopathie ischémique, IC à FE altérée).</li><li>Les <strong>prostaglandines</strong> : proposées en cas d'ischémie critique non revascularisable (perfusions quotidiennes en milieu spécialisé).</li></ul></div>"},{"i":"23d5e1331f54","n":225,"o":"225-6","u":"Suivi et/ou pronostic","t":"Connaître les complications et le pronostic : ischémie aigüe des membres inférieurs, morbimortalité cardiovasculaire","q":"Quel est le rôle de l'Indice de Pression Systolique (IPS) dans l'évaluation du risque cardiovasculaire chez un patient atteint d'AOMI ?","a":"<div class=\"notion-course\"><p>Un <strong>IPS &lt; 0,90</strong> est un <strong>marqueur de risque cardiovasculaire élevé</strong>. Il est associé à un risque accru d'évènements cardiovasculaires majeurs (accident coronarien ou cérébral fatal ou non).</p></div>"},{"i":"2b11fd4097c3","n":225,"o":"225-6","u":"Suivi et/ou pronostic","t":"Connaître les complications et le pronostic : ischémie aigüe des membres inférieurs, morbimortalité cardiovasculaire","q":"Pourquoi dit-on que le pronostic vital de l'artériopathie oblitérante des membres inférieurs (AOMI) est principalement conditionné par la morbimortalité cardiovasculaire ?","a":"<div class=\"notion-course\"><p>L'AOMI est l'expression locale d'une <strong>maladie athéromateuse systémique</strong>. Le pronostic vital est avant tout conditionné par les <strong>atteintes coronariennes</strong> et <strong>cérébrovasculaires</strong> associées, qui sont souvent présentes et doivent être recherchées.</p></div>"},{"i":"a71c2838ba51","n":225,"o":"225-6","u":"Suivi et/ou pronostic","t":"Connaître les complications et le pronostic : ischémie aigüe des membres inférieurs, morbimortalité cardiovasculaire","q":"Quelle est la principale complication aiguë locale de l'artériopathie oblitérante des membres inférieurs (AOMI) et comment survient-elle ?","a":"<div class=\"notion-course\"><p>La principale complication aiguë locale de l'AOMI est l'<strong>ischémie aiguë de membre</strong>. Elle survient principalement par <strong>thrombose in situ</strong> d'une lésion d'AOMI préexistante.</p></div>"},{"i":"c23ad153d651","n":225,"o":"225-6","u":"Suivi et/ou pronostic","t":"Connaître les complications et le pronostic : ischémie aigüe des membres inférieurs, morbimortalité cardiovasculaire","q":"Quel est le pronostic en termes de mortalité et de risque d'amputation pour un patient atteint d'ischémie permanente chronique liée à une AOMI ?","a":"<div class=\"notion-course\"><ul><li>L’ischémie chronique menaçant le membre expose à un risque élevé d’amputation et de décès cardiovasculaire.</li><li>Le risque est nettement supérieur à celui d’une simple claudication et dépend de la plaie, de l’infection, de la perfusion et de la revascularisation ; ne pas lui appliquer le chiffre de 5 % d’amputation à cinq ans.</li></ul></div>"},{"i":"f7706853d44c","n":225,"o":"225-6","u":"Suivi et/ou pronostic","t":"Connaître les complications et le pronostic : ischémie aigüe des membres inférieurs, morbimortalité cardiovasculaire","q":"Quel est le pronostic en termes d'espérance de vie et de mortalité à 5 ans pour un patient présentant une claudication intermittente due à une AOMI ?","a":"<div class=\"notion-course\"><ul><li>L'espérance de vie est <strong>réduite de <span class=\"nc-red nc-bold\">-10 ans</span></strong>.</li><li>La mortalité à 5 ans est de <strong>15 %</strong> si elle évolue vers une ischémie d'effort.</li></ul></div>"},{"i":"212d3456c713","n":225,"o":"225-7","u":"Diagnostic positif","t":"Savoir définir et identifier les manifestations cliniques d’ischémie aiguë complète ou incomplète","q":"Quels sont les signes cliniques indiquant une ischémie aiguë menaçante ou irréversible selon la classification de Rutherford ?","a":"<div class=\"notion-course\"><ul><li><strong>Ischémie menaçante (Grade IIa-IIb)</strong> : présence d'un déficit sensitif (limité aux orteils ou au-delà) et/ou d'un déficit moteur modéré.</li><li><strong>Ischémie irréversible (Grade III)</strong> : présence d'une <strong>anesthésie importante</strong> et d'une <strong>paralysie</strong> importante. D'autres signes d'ischémie dépassée incluent la <strong><span class=\"nc-red nc-bold\">rigidité musculaire</span></strong>, les <strong><span class=\"nc-red nc-bold\">marbrures</span></strong> et les <strong><span class=\"nc-red nc-bold\">phlyctènes</span></strong>.</li></ul></div>"},{"i":"2d7b3ef64466","n":225,"o":"225-7","u":"Diagnostic positif","t":"Savoir définir et identifier les manifestations cliniques d’ischémie aiguë complète ou incomplète","q":"Quels sont les signes fonctionnels et physiques d'une ischémie aiguë d'un membre ?","a":"<div class=\"notion-course\"><ul><li><strong>Signes fonctionnels</strong> : douleur spontanée brutale à type de <strong><span class=\"nc-red nc-bold\">broiement</span></strong>, impotence fonctionnelle du membre.</li><li><strong>Signes physiques</strong> : membre <strong><span class=\"nc-blue_bg\">froid</span>, <span class=\"nc-blue_bg\">pâle</span>, <span class=\"nc-blue_bg\">livide</span></strong>, et <strong><span class=\"nc-blue_bg\">abolition des pouls</span></strong><span class=\"nc-blue_bg\"> en aval de l'occlusion</span>.</li></ul></div>"},{"i":"2f7e3e07b47f","n":225,"o":"225-7","u":"Diagnostic positif","t":"Savoir définir et identifier les manifestations cliniques d’ischémie aiguë complète ou incomplète","q":"Quelle est la définition de l'ischémie aiguë d'un membre ?","a":"<div class=\"notion-course\"><p>L'ischémie <span class=\"nc-red_bg\">aiguë</span> d'un membre correspond à une interruption brutale du flux artériel, entraînant une ischémie tissulaire qui peut aboutir à une nécrose. Il s'agit d'une urgence absolue.</p></div>"},{"i":"60957646eb54","n":225,"o":"225-7","u":"Diagnostic positif","t":"Savoir définir et identifier les manifestations cliniques d’ischémie aiguë complète ou incomplète","q":"Quels sont les délais de souffrance tissulaire des différentes cellules lors d'une ischémie aiguë d'un membre ?","a":"<div class=\"notion-course\"><ul><li><span class=\"nc-yellow_bg\">Cellules nerveuses</span> : <strong>moins de 2 heures</strong>.</li><li><span class=\"nc-yellow_bg\">Cellules musculaires</span> : <strong>6 à 8 heures</strong>.</li><li><span class=\"nc-red_bg\">Nécrose cutanée</span> : à partir de <strong>24 heures</strong>.</li></ul></div>"},{"i":"71e6120491ad","n":225,"o":"225-7","u":"Diagnostic positif","t":"Savoir définir et identifier les manifestations cliniques d’ischémie aiguë complète ou incomplète","q":"Comment différencier cliniquement une ischémie aiguë complète d'une ischémie aiguë incomplète d'un membre ?","a":"<div class=\"notion-course\"><p>L'<strong>ischémie complète</strong> est caractérisée par la présence d'une <strong>paralysie</strong>, c'est-à-dire l'impossibilité de <span class=\"nc-red nc-bold\">mobiliser les orteils</span> ou de <span class=\"nc-red nc-bold\">relever le pied</span> (atteinte du nerf fibulaire commun). Son absence signe l'ischémie incomplète.</p></div>"},{"i":"20825a6b1528","n":225,"o":"225-9","u":"Identifier une urgence","t":"Connaître les principes d’un traitement en urgence","q":"Quel bilan étiologique et traitement au long cours sont préconisés après la revascularisation d'une ischémie aiguë de membre ?","a":"<div class=\"notion-course\"><ul><li>Bilan étiologique et prévention secondaire : source embolique (FA, thrombus intracardiaque), thrombose sur <span class=\"nc-red_bg\">AOMI</span> ou anévrisme ; traitement antithrombotique et vasculaire adapté.</li></ul></div>"},{"i":"2da7d4f5e4c4","n":225,"o":"225-9","u":"Identifier une urgence","t":"Connaître les principes d’un traitement en urgence","q":"Quelles sont les techniques de revascularisation privilégiées selon la cause de l'ischémie aiguë de membre ?","a":"<div class=\"notion-course\"><ul><li>Rutherford I : membre viable, imagerie urgente permettant de planifier le traitement. IIa : menace marginale sans déficit moteur, revascularisation urgente ; une thrombolyse dirigée peut être discutée. IIb : déficit moteur, revascularisation immédiate ; aucune imagerie ou thrombolyse lente ne doit retarder le sauvetage.</li><li>Technique adaptée à l’anatomie et à la cause : thrombectomie/embolectomie, chirurgie de reconstruction, traitement endovasculaire ou stratégie hybride.</li></ul></div>"},{"i":"3284541ea3e8","n":225,"o":"225-9","u":"Identifier une urgence","t":"Connaître les principes d’un traitement en urgence","q":"Quel est le traitement préventif et curatif du syndrome de revascularisation ?","a":"<div class=\"notion-course\"><ul><li>Après reperfusion : surveiller <span class=\"nc-red nc-bold\">syndrome des loges</span>, potassium, ECG, fonction rénale, <span class=\"nc-blue_bg\">CPK</span>, acidose et <span class=\"nc-blue_bg\">diurèse</span>. Aponévrotomie si <span class=\"nc-red nc-bold\">syndrome des loges</span> ou selon le risque. Une <span class=\"nc-orange_bg\">hyperkaliémie</span> menaçante nécessite le protocole d’urgence (protection myocardique si indiquée, transfert intracellulaire et élimination) ; un chélateur seul ne suffit pas. Bicarbonates et épuration sont discutés selon les anomalies, non systématiques.</li></ul></div>"},{"i":"3fae9e92604f","n":225,"o":"225-9","u":"Identifier une urgence","t":"Connaître les principes d’un traitement en urgence","q":"Quel est le traitement médical immédiat de première intention pour une ischémie aiguë de membre, avant revascularisation ?","a":"<div class=\"notion-course\"><ul><li>Appel vasculaire immédiat, évaluation de la viabilité du membre et de l’état général. Une atteinte motrice signe une menace immédiate ; ne pas attendre un délai théorique de six heures pour agir.</li><li><span class=\"nc-pink_bg\">HNF</span> IV dès le diagnostic sauf contre-indication, avec surveillance selon le protocole, antalgie, voie veineuse et bilan préopératoire. Protéger le membre, éviter compression, lésions cutanées et chaleur directe ; oxygène si hypoxémie.</li></ul></div>"},{"i":"5b3e5b667ecb","n":225,"o":"225-9","u":"Identifier une urgence","t":"Connaître les principes d’un traitement en urgence","q":"Dans quel cas et pourquoi une aponévrotomie jambière est-elle indiquée ou discutée dans la prise en charge de l'ischémie aiguë de membre ?","a":"<div class=\"notion-course\"><ul><li>Après reperfusion : surveiller <span class=\"nc-red nc-bold\">syndrome des loges</span>, potassium, ECG, fonction rénale, <span class=\"nc-blue_bg\">CPK</span>, acidose et <span class=\"nc-blue_bg\">diurèse</span>. Aponévrotomie si <span class=\"nc-red nc-bold\">syndrome des loges</span> ou selon le risque. Une <span class=\"nc-orange_bg\">hyperkaliémie</span> menaçante nécessite le protocole d’urgence (protection myocardique si indiquée, transfert intracellulaire et élimination) ; un chélateur seul ne suffit pas. Bicarbonates et épuration sont discutés selon les anomalies, non systématiques.</li></ul></div>"},{"i":"7db8d0aace5e","n":225,"o":"225-9","u":"Identifier une urgence","t":"Connaître les principes d’un traitement en urgence","q":"Quand une amputation est-elle indiquée dans la prise en charge de l'ischémie aiguë de membre ?","a":"<div class=\"notion-course\"><ul><li>Grade III : anesthésie profonde, paralysie/rigidité et lésions irréversibles ; amputation primaire habituellement indiquée après évaluation spécialisée. La revascularisation d’un membre non viable expose à une reperfusion dangereuse.</li></ul></div>"},{"i":"a3bafcd188e4","n":225,"o":"225-9","u":"Identifier une urgence","t":"Connaître les principes d’un traitement en urgence","q":"Quelles sont les principales complications métaboliques et rénales du syndrome de revascularisation après ischémie aiguë de membre ?","a":"<div class=\"notion-course\"><p>Le syndrome de revascularisation peut causer :</p><ul><li><strong><span class=\"nc-orange_bg\">Hyperkaliémie</span></strong></li><li><strong><span class=\"nc-orange_bg\">Hyperuricémie</span></strong></li><li><strong><span class=\"nc-orange_bg\">Hyperphosphorémie</span></strong></li><li><strong><span class=\"nc-orange_bg\">Acidose métabolique</span></strong></li><li><strong><span class=\"nc-red nc-bold\">Hypocalcémie</span></strong></li><li><strong><span class=\"nc-blue_bg\">Myoglobinémie</span> / <span class=\"nc-blue_bg\">Myoglobinurie</span></strong></li><li><strong>CIVD</strong> (<span class=\"nc-orange_bg\">Coagulation Intravasculaire Disséminée</span>)</li><li><strong>Insuffisance rénale aiguë</strong> par <span class=\"nc-red nc-bold\">nécrose tubulaire aiguë</span>.</li></ul></div>"},{"i":"ad541ce1a062","n":225,"o":"225-9","u":"Identifier une urgence","t":"Connaître les principes d’un traitement en urgence","q":"Quel est le délai impératif de revascularisation en cas d'ischémie aiguë de membre ?","a":"<div class=\"notion-course\"><ul><li>Appel vasculaire immédiat, évaluation de la viabilité du membre et de l’état général. Une atteinte motrice signe une menace immédiate ; ne pas attendre un délai théorique de six heures pour agir.</li><li>Rutherford I : membre viable, imagerie urgente permettant de planifier le traitement. IIa : menace marginale sans déficit moteur, revascularisation urgente ; une thrombolyse dirigée peut être discutée. IIb : déficit moteur, revascularisation immédiate ; aucune imagerie ou thrombolyse lente ne doit retarder le sauvetage.</li></ul></div>"},{"i":"776a666cdc73","n":225,"o":"225-1","u":"Définition","t":"Connaître la définition et la fréquence de l’artériopathie oblitérante des membres inférieurs (AOMI)","q":"Quels sont les points clés concernant la définition et la fréquence de l’artériopathie oblitérante des membres inférieurs (AOMI) ?","a":"<div class=\"notion-course\"><ul><li>L'<span>AOMI</span> est définie par la présence de <span>lésions d'athérosclérose de l'aorte et des artères des membres inférieurs</span>, pouvant entraîner des <span><span class=\"nc-red\"><span class=\"nc-red\">plaques</span></span></span>, des <span><span class=\"nc-red\"><span class=\"nc-red\">sténoses</span></span></span> ou des <span><span class=\"nc-red\"><span class=\"nc-red\">obstructions</span></span></span> athéromateuses d'une ou plusieurs artères destinées aux membres inférieurs. Elle représente l'<span>expression locale d'une maladie systémique</span> : le <span>pronostic</span> est en grande partie conditionné par les complications cardiaques et cérébrovasculaires.</li><li>L'origine athéromateuse domine très largement : l'AOMI correspond à <span>&gt; 95 %</span> des atteintes artérielles oblitérantes des membres inférieurs.</li><li><strong>Fréquence</strong> — la <span>prévalence</span> augmente avec l'âge et atteint <span>&gt; 20 %</span> au-delà de <span>70 ans</span>. Elle doit être <strong>recherchée systématiquement</strong> à partir de <span>60 ans</span>.</li></ul></div>"},{"i":"2fe1f3fc5c35","n":225,"o":"225-2","u":"Physiopathologie","t":"Connaître l’étiologie et les facteurs de risque de l’AOMI","q":"Quels sont les points clés concernant l’étiologie et les facteurs de risque de l’AOMI ?","a":"<div class=\"notion-course\"><ul><li>L'<span>origine athéromateuse</span> de l'AOMI est de très loin la plus fréquente (<span>&gt; 95 %</span>). L'AOMI est l'expression locale d'une maladie systémique : son <span>pronostic</span> est conditionné par les atteintes <span>cardiaques</span> (<span>angor</span>, <span>infarctus du myocarde</span>) et <span>cérébrovasculaires</span> associées.</li><li><strong><span>Facteurs de risque</span></strong> — ce sont les <span>facteurs de risque cardiovasculaire</span> : âge, <span><span class=\"nc-red_bg\"><span class=\"nc-red_bg\">tabac</span></span></span>, <span><span class=\"nc-red_bg\"><span class=\"nc-red_bg\">diabète</span></span></span>, <span>HTA</span>, <span>hypercholestérolémie</span>. Les <strong>FR dominants</strong> de l'AOMI sont le <span><span class=\"nc-red_bg\"><span class=\"nc-red_bg\">tabac</span></span></span> et le <span><span class=\"nc-red_bg\"><span class=\"nc-red_bg\">diabète</span></span></span>.</li><li><strong>Artériopathies non athéromateuses</strong> — elles représentent moins de <span>5 %</span> des atteintes oblitérantes des membres inférieurs :</li><li><strong>Artériopathies inflammatoires :</strong> maladie de <span><span class=\"nc-orange_bg\"><span class=\"nc-orange_bg\">Buerger</span></span></span>, <span><span class=\"nc-orange_bg\"><span class=\"nc-orange_bg\">Takayasu</span></span></span>, <span><span class=\"nc-orange_bg\"><span class=\"nc-orange_bg\">Horton</span></span></span>, certaines collagénoses (<span class=\"nc-orange_bg\"><span class=\"nc-orange_bg\">périartérite noueuse</span></span>, <span><span class=\"nc-orange_bg\"><span class=\"nc-orange_bg\">lupus</span></span></span>).</li></ul></div>"},{"i":"ff1c0767c8e5","n":225,"o":"225-8","u":"Etiologies","t":"Connaître les autres causes de l’ischémie aiguë","q":"Quels sont les points clés concernant les autres causes de l’ischémie aiguë ?","a":"<div class=\"notion-course\"><ul><li>Deux grands mécanismes sont à distinguer : la <span>thrombose artérielle in situ</span> et l'<span>embolie sur artères saines</span>.</li><li><strong>Sur artères pathologiques :</strong> <span><span class=\"nc-red_bg\"><span class=\"nc-red_bg\">AOMI</span></span></span> ++++ ; artériopathies non athéromateuses ; anévrisme poplité thrombosé ; <span>dissection</span> <span class=\"nc-brown_bg nc-bold\"><span class=\"nc-brown_bg nc-bold\">aorto</span></span>-<span class=\"nc-brown_bg nc-bold\"><span class=\"nc-brown_bg nc-bold\">iliaque</span></span>.</li><li><strong>Sur artères saines :</strong> <span>déshydratation</span> / hémoconcentration ; kyste adventiciel ; thrombophlébite <span>ischémique</span> ; <span>coagulopathies</span> et thrombophilies ; <span>thrombopénie induite par l'héparine</span> ; <span>SAPL</span>.</li><li><strong>Causes cardiaques :</strong> <span>fibrillation atriale</span> +++ ; <span class=\"nc-red_bg\"><span class=\"nc-red_bg\">valvulopathies</span></span> ; foramen ovale perméable, anévrisme du septum interatrial ; <span>IDM</span>, dyskinésie ou anévrisme du VG ; tumeurs cardiaques (myxome de l'atrium).</li></ul></div>"},{"i":"e32ced74fce3","n":225,"o":"225-11","u":"Etiologies","t":"Connaître les principales étiologies des anévrismes de l’aorte abdominale et les principes du dépistage","q":"Quels sont les points clés concernant les principales étiologies des anévrismes de l’aorte abdominale et les principes du dépistage ?","a":"<div class=\"notion-course\"><ul><li>Les facteurs majeurs d’AAA sont âge, sexe <span class=\"nc-red_bg\">masculin</span>, <span class=\"nc-red_bg\">tabagisme</span> et antécédents familiaux. Le mécanisme comporte une dégradation de la matrice pariétale ; l’association à l’athérome ne signifie pas que l’AAA est une simple plaque dilatée.</li><li>Le diabète est associé dans les études à une moindre fréquence/croissance des AAA, sans constituer une protection clinique à rechercher. Le mécanisme ne se résume pas à la médiacalcose.</li><li>Autres causes ou contextes : maladie inflammatoire/infectieuse, maladie du tissu conjonctif, évolution après <span class=\"nc-red\">dissection</span> ; distinguer anévrisme vrai et faux anévrisme.</li><li><span class=\"nc-yellow_bg nc-bold\">Dépistage</span> ciblé par échographie : repère HAS, <span class=\"nc-red nc-bold\">hommes</span> de 65 à 75 ans fumeurs ou anciens fumeurs, et <span class=\"nc-red nc-bold\">hommes</span> de 50 à 75 ans avec antécédent familial d’AAA. D’autres recommandations proposent des populations plus larges : préciser la source plutôt que présenter tous les adultes de 60 à 85 ans comme une indication universelle.</li></ul></div>"},{"i":"e45a67268087","n":225,"o":"225-14","u":"Prise en charge","t":"Connaître les principes thérapeutiques d’un anévrisme de l’aorte abdominale","q":"Quels sont les points clés concernant les principes thérapeutiques d’un anévrisme de l’aorte abdominale ?","a":"<div class=\"notion-course\"><ul><li>Contrôler les facteurs cardiovasculaires, surtout arrêter le tabac ; aucun médicament n’a démontré une capacité suffisante à faire disparaître un AAA et à remplacer sa surveillance.</li><li>AAA asymptomatique : suivi échographique adapté au diamètre, au sexe et à la croissance, avec avis vasculaire. Ne pas utiliser un calendrier unique indépendant du diamètre.</li><li>Repères d’intervention élective : diamètre ≥ 55 mm chez l’homme ; discussion autour de <span class=\"nc-pink nc-bold\">50 mm</span> chez la femme, en tenant compte du risque opératoire <span class=\"nc-yellow_bg\">et de</span> l’anatomie. Une <span class=\"nc-brown_bg\">croissance</span> rapide (environ ≥ 10 mm/an, à confirmer par une mesure fiable), une morphologie particulière ou des symptômes modifient la décision.</li><li>AAA douloureux ou compliqué : évaluation urgente, indépendamment du seuil de diamètre.</li></ul></div>"}],"courseEdition":{"source":"notion","notionUrl":"https://app.notion.com/p/2ad37f85d9418121a8bae0f610f004f4?pvs=204","reviewedAt":"2026-10-15","note":"Cours, cartes et arbres relus. Couleurs des passages Notion correspondants ; références et compléments identifiés dans chaque objectif."}};
